const subclassSummaryOverrides: Readonly<Record<string, string>> = {
  // ===== 邪术师宗主（v1.5.1）=====
  'subclass-2014-warlock-archfey': '宗主是一位妖精领主或女王，守护着凡人种族出现前就已被遗忘的秘密，行为往往难以理解。1 级获得扩展法术列表与妖精仪态；6 级雾遁；10 级斗转星移；14 级幻影黑幕。',
  'subclass-2014-warlock-fiend': '宗主是下层位面的强大邪魔（恶魔领主或大魔鬼），追求万物的堕落与毁灭，但你不必与之同流合污。1 级获得扩展法术列表与黑暗赐福；6 级黑暗强运；10 级邪魔体魄；14 级直坠噩梦。',
  'subclass-2014-warlock-great-old-one': '宗主的本质与现实结构格格不入，可能来自遥远国度或仅存于传说中的古神，其行为无法被凡人理解，也可能根本未意识到你的存在。1 级获得扩展法术列表与唤醒心灵；6 级熵光结界；10 级思维之盾；14 级创造奴仆。',
  'subclass-2014-warlock-undying': 'The Undying · SCAG · 宗主已解开永恒生命的秘密，可能是维克那、巫妖女王沃尔或艾伦诺的不朽王庭。1 级获得扩展法术列表与「历经死亡」（额外习得戏法维生术，对抗疾病豁免具有优势，亡灵难以直接伤害你）；6 级祛死可在死亡豁免成功时回复 1d8＋体质调整值生命值；10 级不灭本质让你停止衰老、无需饮食呼吸，并可用动作恢复 1d8＋体质调整值生命值（长休后恢复使用）；14 级不灭生命可在生命值降至 0 时以反应恢复等于 1d8＋体质调整值的生命值（长休或短休后恢复使用）。',
  'subclass-2014-warlock-celestial': 'The Celestial · XGtE · 与至高天、羽蛇、斯芬克斯或独角兽等上层位面存在缔约，沐浴圣洁辉光。3 级获得始终准备的天界法术与治愈之光（1＋魔契师等级枚 d6 的骰池，附赠动作消耗至多等于魅力调整值的骰子治疗 60 尺内的自己或他人，长休恢复）；6 级光耀之魂使火焰与光耀伤害的加成与治疗量提升等于魅力调整值；10 级天界韧性让自己与盟友在短休后获得临时生命值；14 级灼光复仇在濒死时爆发出治疗与致盲的辉光。',
  'subclass-2014-warlock-hexblade': 'The Hexblade · XGtE · 与堕影冥界的智能武器之力缔约，以诅咒与暗影增幅战斗。1 级获得扩展法术列表、咒剑诅咒（附赠动作标记 30 尺内目标，对其伤害掷骰加熟练加值、命中 19—20 即为重击，击杀后可用附赠动作转移）与巫咒战士（以魅力替代力量或敏捷进行武器攻击，并可让单手持用武器成为法器）；6 级咒缚恶灵在击杀后召出服从你的幽魂；10 级巫咒盔甲可用反应让被诅咒目标的攻击失手；14 级巫咒大师让咒剑诅咒可转移到新目标。',
  'subclass-2014-warlock-fathomless': 'The Fathomless · TCoE · 汲取大洋、水元素位面或异界海洋的无尽之力。1 级获得扩展法术列表、深海触手（附赠动作在 60 尺内召出触手攻击并造成寒冷伤害，可减伤并推开目标）与海洋之赐（获得等于速度的游泳速度并在水下呼吸）；6 级海洋之魂使你在水下与 60 尺内生物心灵相通，并让触手造成的伤害忽视寒冷抗性；10 级守卫缠绕让触手可用反应减少你或 10 尺内盟友所受的伤害；14 级缠绕触手可无需法术位施展艾伐黑触手（每次长休一次）。',
  'subclass-2014-warlock-genie': 'The Genie · TCoE · 与元素位面的巨灵贵族缔约，可选定土、气、火、水其中之一。1 级获得扩展法术列表（含所选巨灵的专属法术）与巨灵容器（获得一件可进入休憩的微小容器，短休时可在其中回复额外生命值，并附带一种元素伤害加值）；6 级元素之赐获得所选元素抗性、20 尺飞行速度（持续 10 分钟，熟练加值次）与元素伤害强化；10 级圣所容器让短休进入容器时全队获得临时生命值；14 级有限愿望可请求实现一个有限效果（每 1d4 次长休一次）。',
  'subclass-2014-warlock-undead': 'The Undead · VRGtR · 与巫妖、古老吸血鬼等蔑视生死轮回的存在缔约。1 级获得始终准备的死灵法术与战栗形态（附赠动作变身 1 分钟，免疫恐慌、获得等于 1d10＋魔契师等级 的临时生命值，并可用附赠动作让 30 尺内一名生物恐慌；次数等于魅力调整值）；6 级坟冢之触使一次攻击命中可转化为死灵伤害并禁止目标回复生命值；10 级死疽躯壳让你可用反应把受到的伤害转为黯蚀伤害并反噬攻击者；14 级超凡恐惧可投射灵魂脱离躯体，获得飞行与穿墙等能力。',

  // ===== 奇械师（TCoE）=====
  'subclass-2014-artificer-alchemist': 'Alchemist · TCoE · 把奇异原料混合成延续生命或夺走生命的物质，是奇械师最古老的技艺。3 级获得炼金工具熟练与始终准备的炼金师法术，并能以长休制造实验性灵药（治疗、疾速、韧性、气魄、飞行、变形六选一，6 级 2 瓶、15 级 3 瓶）；5 级炼金术掌握让法器施法的治疗或强酸／火焰／暗蚀／毒素伤害获得智力加值；9 级复原药剂为饮用者附加临时生命，并可免费施展次等复原术；15 级化学专家获得强酸与毒素抗性、免疫中毒，并各免费施展一次高级复原术与医疗术。',
  'subclass-2014-artificer-armorer': 'Armorer · TCoE · 把护甲变成第二层皮肤，以奥能装甲承载奇械师魔法。3 级获得重甲与铁匠工具熟练、始终准备的装甲师法术，可将护甲转为奥能装甲并选定装甲型号（守护者偏前线与临时生命／渗透者偏远程闪电与机动，短休或长休后可用铁匠工具更换）；5 级额外攻击；9 级装甲改造让奥能装甲的各部分分别承受注法并追加 2 个注法位；15 级完美装甲按型号强化攻击与防护。',
  'subclass-2014-artificer-artillerist': 'Artillerist · TCoE · 在战场上投射能量与爆炸物的专家，以魔能炮台构筑火力点。3 级获得木匠工具熟练与始终准备的魔炮师法术，能以动作召唤小型或微型魔能炮台并选定型号（投火机／力场弩炮／防御者），每回合可用附赠动作激活 60 尺内的炮台；5 级奥法枪械让魔杖、法杖或权杖成为法器并使法术伤害掷骰获得 d8 加值；9 级高爆炮台使伤害骰 +1d8 并可命令炮台自爆；15 级要塞阵地提供半身掩护并可同时维持两台炮台。',
  'subclass-2014-artificer-battle-smith': 'Battle Smith · TCoE · 守护者与医生的结合，携带自制的钢铁守卫重整战线。3 级获得铁匠工具与军用武器熟练、始终准备的战地匠师法术，可用智力替代力量或敏捷进行魔法武器攻击，并造出钢铁守卫（使用你的先攻、需附赠动作下达指令，伤害免疫毒素）；5 级额外攻击；9 级奥能震荡可在攻击命中时追加 2d6 力场伤害或为 30 尺内目标恢复 2d6 生命，次数等于智力调整值；15 级改良守卫把奥能震荡提升为 4d6，守卫 AC +2 且偏转攻击反伤。',

  // ===== 野蛮人原初道途 =====
  'subclass-2014-barbarian-berserker': 'Path of the Berserker · PHB · 以纯粹的暴怒作战，把狂暴推向极致。3 级狂乱可在狂暴期间以附赠动作追加一次近战武器攻击（结束后获得一层力竭）；6 级无我狂暴使狂暴期间免疫魅惑与恐慌；10 级恐吓气势可以动作使 30 尺内一名生物恐慌；14 级报复使你在狂暴期间被近战命中时可用反应反击。',
  'subclass-2014-barbarian-totem-warrior': 'Path of the Totem Warrior · PHB · 与猛兽之灵共鸣，按所选图腾获得对应的狂暴增益。3 级图腾精魄（熊／鹰／狼三选一）；6 级兽之形按同一图腾提供非狂暴期能力；10 级图腾行者可施展野兽知觉与野兽沟通仪式；14 级图腾协调按图腾提供更强效果。',
  'subclass-2014-barbarian-ancestral-guardian': 'Path of the Ancestral Guardian · XGtE · 以先祖精魂守护族人、削弱敌人。3 级先祖护卫在狂暴时召出精魂战士：你每回合首个命中的目标对你以外者攻击具有劣势，且其命中他人时该次伤害被减免；6 级精魂之盾可用反应为 30 尺内可见生物减少 2d6 伤害（10 级 3d6、14 级 4d6）；10 级问道精魂可无需法术位施展卜筮术或鹰眼术（感知施法）；14 级仇魂先祖使被精魂标记的目标受到反伤。',
  'subclass-2014-barbarian-battlerager': 'Path of the Battlerager · SCAG · 限定矮人的道途，披挂钉刺甲以身体冲撞作战。3 级战狂装甲使你在狂暴期间可附赠动作以钉刺甲对 5 尺内目标发动近战攻击（1d4 穿刺），并以攻击动作擒抱成功时造成 3 点穿刺伤害；6 级凶蛮无羁使鲁莽攻击时获得等于体质调整值的临时生命；10 级战狂冲锋可在狂暴期间以附赠动作疾走；14 级钉刺反冲让 5 尺内近战命中你的攻击者受到 3 点穿刺伤害。',
  'subclass-2014-barbarian-beast': 'Path of the Beast · TCoE · 点燃灵魂深处的兽性火花，狂暴时变形长出天生武器。3 级野兽之形在进入狂暴时选择啃咬（1d8 穿刺，半血以下命中可恢复生命）、爪击（1d6 挥砍，一回合追加一次）或尾击（1d8 穿刺，触及并可反应加 AC）；6 级兽性之魂使天生武器视为魔法武器，并在休息后选择泳速与水下呼吸、攀爬速度或延长跳跃；10 级狂怒之染让命中目标进行感知豁免，失败则被迫攻击同伴或受 2d12 心灵伤害；14 级狩猎之唤可激发盟友的凶性。',
  'subclass-2014-barbarian-giant': 'Path of the Giant · Bigby · 从巨人与元素同族汲取力量，狂暴时自身体型增大。3 级巨人之力获得巨人语并能习得德鲁伊伎俩或奇术（感知施法），巨人之灾让狂暴期间投掷武器附加狂暴伤害、触及 +5 尺且体型增至大型；6 级元素战刃可在狂暴时为持握武器注入强酸／寒冷／火焰／雷鸣／闪电并额外造成 1d6，武器获得投掷属性且脱手后立即回手；10 级伟力推动可用附赠动作把不超过中型的生物投向 30 尺内；14 级创世巨像使触及再增 10 尺、体型可至巨型并扩大投掷对象。',
  'subclass-2014-barbarian-storm-herald': 'Path of the Storm Herald · XGtE · 把愤怒化作环绕自身的原初风暴披风。3 级风暴灵光在狂暴时选择沙漠（火焰伤害）、海洋（闪电束）或冻原（削减目标伤害掷骰），形成 10 尺光环并可以附赠动作再次激活；6 级风暴之魂按已选环境提供火焰／闪电／寒冷抗性与对应小能力；10 级风暴之盾让光环内选定盟友获得同类型抗性；14 级狂怒风暴按环境强化光环效果。',
  'subclass-2014-barbarian-wild-magic': 'Path of Wild Magic · TCoE · 狂暴源自妖精荒野的狂野魔力，效果不受控。3 级魔法察觉可以动作感知 60 尺内的法术与魔法物品（次数等于熟练加值），狂暴时触发狂野浪潮（按 d8 表产生暗蚀卷须、传送、精魂爆炸等效果）；6 级魔法共鸣使狂暴期间的力量检定与豁免获得额外 1d3；10 级不稳定反冲可在受伤或失败时以反应重掷一次狂野浪潮；14 级控制乱流可在狂暴时指定狂野浪潮的结果。',
  'subclass-2014-barbarian-zealot': 'Path of the Zealot · XGtE · 以神祇之名狂战，死后仍可被复活。3 级神性之怒使狂暴期间每回合首次命中额外造成 1d6＋半个野蛮人等级的光耀或黯蚀伤害，神之勇者提供 4 枚 d12 的治疗池（6／12／17 级增至 5／6／7 枚，长休恢复）；6 级专心炽志每次狂暴可重骰一次失败的豁免并获得狂暴伤害加值；10 级狂热威仪以附赠动作让 60 尺内至多十名生物的攻击与豁免具有优势（每次长休一次，可消耗狂暴次数重置）；14 级神之狂暴可进入 1 分钟的圣斗士姿态，获得飞行等增益。',

  // ===== 武僧宗派（D1 第三批）=====
  'subclass-2014-monk-open-hand': 'Way of the Open Hand · PHB · 无论是用拳头还是兵刃都是终极的战技大师，精通击退、绊倒与以气自疗。3 级散打技巧让疾风连击命中的目标承受敏捷豁免倒地、力量豁免被推开至多 15 尺，或直到你下回合结束前无法执行反应；6 级混元体以动作恢复三倍武僧等级的生命值（每次长休一次）；11 级宁神境在长休后获得庇护术效应（豁免 DC 为 8＋感知调整值＋熟练加值）；17 级渗透劲消耗 3 点气把暗劲送入命中目标体内，以动作终止劲力时目标须通过体质豁免，失败则生命值降为 0，成功仍受 10d10 暗蚀伤害。',
  'subclass-2014-monk-shadow': 'Way of Shadow · PHB · 追寻隐匿与遁术之道的忍者与影舞者，在微光与黑暗中行动自如。3 级暗影技艺可以用动作消耗 2 点气施展黑暗术、黑暗视觉、行动无踪或沉默术（无需材料成分），并免费获得次级幻象戏法；6 级暗影步在微光或黑暗环境中以附赠动作传送至多 60 尺，并获得本回合下一次近战攻击的优势；11 级幽影斗篷在微光或黑暗中以动作隐形，攻击、施法或进入明亮光照时结束；17 级灵机一斩可在 5 尺内生物被他人命中时以反应对其发动一次近战攻击。',
  'subclass-2014-monk-four-elements': 'Way of the Four Elements · PHB · 以运气凝神驱使元素，把气化为水、火、土、风的具现。3 级四象门徒习得元素同调与另一个自选法门，法门均以气驱动（飞炎击 2 点气施展燃烧之手、四雷拳 2 点气施展雷鸣波、凝气刚拳 2 点气造成 3d10 钝击并推开目标至多 20 尺且使其倒地、身化长流 1 点气塑形 120 尺内的冰与水），6／11／17 级各再学一个新法门并可替换一个已知法门；5 级起可额外消耗气提升法门法术的环阶，单次施法消耗上限随等级由 3 点提升到 6 点；法门还包含寒冬之息（寒冰锥）、苍山庇佑（石肤术）、凤凰烈焰（火球术）、攀云步（飞行术）与滚石流（石墙术）等。',
  'subclass-2014-monk-long-death': 'Way of the Long Death · SCAG · 痴迷于死亡的结构与意义，从临终瞬间提炼致命武艺。3 级往生咒在你使 5 尺内的生物生命值降为 0 时获得 感知调整值＋武僧等级 点临时生命值（至少 1 点）；6 级索命镰以动作展现死亡阴影，30 尺内能看见你的生物须通过感知豁免，否则恐慌你直到你下回合结束；11 级握生死在你生命值降为 0 时无需动作消耗 1 点气，改为保留 1 点生命值；17 级永亡触以动作消耗 1 至 10 点气触碰 5 尺内的生物，其体质豁免失败则每点气受 2d10 暗蚀伤害，成功减半。',
  'subclass-2014-monk-sun-soul': 'Way of the Sun Soul · SCAG · 把自身生命能量引导为炽热光芒，以光耀之力远攻近守。3 级耀阳箭获得一次 30 尺远程法术攻击，伤害骰随武艺骰成长并造成光耀伤害，作为攻击动作的一部分使用时还可消耗 1 点气以附赠动作追加两次；6 级热能袭在攻击动作后消耗 2 点气以附赠动作施展燃烧之手，可额外消耗气提升环阶（总消耗不超过武僧等级的一半）；11 级焰阳爆以动作把光球投向 150 尺内任意一点，20 尺半径内的生物体质豁免失败受 2d6 光耀伤害，每多消耗 1 点气追加 2d6（至多 3 点）；17 级太阳盾散发 30 尺明亮光照与其外 30 尺微光，被近战攻击命中时以反应造成 5＋感知调整值 点光耀伤害。',
  'subclass-2014-monk-drunken-master': 'Way of the Drunken Master · XGtE · 以摇摆蹒跚的假动作掩盖精密的格挡、推拿与摔打。3 级附赠熟练获得表演技能与酿酒工具熟练，醉拳技巧让你每次使用疾风连击都同时获得撤离动作的好处，步行速度增加 10 尺直到本回合结束；6 级微醺摇摆让倒地时只花 5 尺移动力起身，并可用 1 点气作反应把失手的近战攻击转给 5 尺内由你选择的另一名可见生物；11 级醉汉机运可消耗 2 点气抵消一次属性检定、攻击检定或豁免检定的劣势；17 级酣醉若狂让疾风连击最多追加三次攻击（合计五次），但每次攻击都必须以不同生物为目标。',
  'subclass-2014-monk-kensei': 'Way of the Kensei · XGtE · 沉浸器械训练，把武器视为身体的延伸与展现武道之美的工具。3 级剑圣之途选定一把近战与一把远程武器作为剑圣武器（6／11／17 级各再添一把），灵巧格挡在持握近战剑圣武器并以徒手打击作为攻击动作一部分时令 AC 获得 +2，持弓审固以附赠动作让剑圣武器的远程命中追加 1d4 同类型伤害，书画之道获得书法或画家工具熟练；6 级人剑合一让剑圣武器的攻击视为魔法，并每回合一次在命中时消耗 1 点气追加一枚武艺骰的伤害；11 级锋锐剑影以附赠动作消耗至多 3 点气为接触的武器提供等值的攻击与伤害加值 1 分钟；17 级精妙剑法每回合一次可重骰失手的武僧武器攻击。',
  'subclass-2014-monk-astral-self': 'Way of the Astral Self · TCoE · 相信身体只是幻觉，把气视为真实形态星我，并将其具现为幽光化身。3 级星我之臂以附赠动作消耗 1 点气召出 10 分钟，出现时 10 尺内由你选定的可见生物敏捷豁免失败受两枚武艺骰的力场伤害，期间可用感知代替力量检定与豁免，并以感知进行触及增加 5 尺、伤害转为力场的徒手打击；6 级星我之容同样以 1 点气召出，提供 120 尺黑暗视觉、感知（洞悉）与魅力（威吓）检定优势，以及只让 60 尺内指定生物听见的私语或 600 尺扩音；11 级星我之躯在手臂与面容同时存在时自动显现，以反应减少 1d10＋感知调整值 点强酸、寒冷、火焰、力场、闪电或雷鸣伤害，并每回合一次追加一枚武艺骰的伤害；17 级星我觉醒消耗 5 点气同时召出三者并使其觉醒，AC 获得 +2，额外攻击可改为三次星我之臂攻击。',
  'subclass-2014-monk-mercy': 'Way of the Mercy · TCoE · 操纵他人的生命能量，对需要帮助者施治、对无可救药者施以痛快。3 级命流之器获得洞悉、医药与草药工具熟练及一副面具，予命之手以动作消耗 1 点气触碰治疗 一枚武艺骰＋感知调整值 点生命值（也可替换疾风连击中的一次徒手打击），夺命之手在徒手打击命中时消耗 1 点气追加同额暗蚀伤害（每回合一次）；6 级生死之触让予命之手额外结束一种疾病或目盲、耳聋、麻痹、中毒、震慑状态，夺命之手可使目标中毒直到你下回合结束；11 级活杀自在让疾风连击的每次徒手打击都可替换为予命之手，命中时还能不额外耗气地使用夺命之手；17 级命极之手以动作消耗 5 点气触碰死亡不超过 24 小时的尸体使其复活并恢复 4d10＋感知调整值 点生命值（每次长休一次）。',
  'subclass-2014-monk-ascendant-dragon': 'Way of the Ascendant Dragon · FTD · 模仿龙之姿态与巨龙伟力共鸣，最终展开龙翼飞天。3 级龙之徒让你能说读写龙语，把徒手打击的伤害类型改为强酸、寒冷、火焰、闪电或毒素之一，并在魅力（威吓或游说）检定失败时以反应重骰（一旦借此由失败转为成功即须长休才能再用）；3 级龙之息可把攻击动作中的一次攻击替换为 20 尺锥状或 30 尺长 5 尺宽的吐息，范围内生物敏捷豁免失败受两枚武艺骰伤害（11 级提升为三枚，使用次数等于熟练加值，用尽后可花 2 点气）；6 级龙翼翱翔在使用飞檐走壁时展开龙翼，获得等于步行速度的飞行速度（次数等于熟练加值）；11 级古龙姿以附赠动作散发 10 尺灵光 1 分钟，选择骇人威仪（感知豁免失败者恐慌你 1 分钟）或抗性（你与灵光内盟友获得所选伤害类型抗性，再次使用需 3 点气）；17 级神龙身让吐息可耗 1 点气扩为 60 尺锥状或 90 尺线状并造成四枚武艺骰伤害，另获 10 尺盲视与怒气爆发（灵光内选定生物敏捷豁免失败受 3d10 所选类型伤害）。',

  // ===== 圣武士神圣誓言（D1 第三批）=====
  'subclass-2014-paladin-devotion': 'Oath of Devotion · PHB · 以公正、美德与秩序为信条的圣骑兵与白骑士，是身披闪亮盔甲的正派骑士典范。3 级获得奉献圣誓法术（防护善恶、庇护术等）与两种引导神力：神圣武器以动作向持握的武器注入正能量 1 分钟，攻击检定加上魅力调整值（至少 +1），散发 20 尺明亮光照与其外 20 尺微光，非魔法武器在此期间视为魔法武器；驱散不洁迫使 30 尺内能看见圣徽或听见祷言的亡灵与邪魔进行感知豁免，失败者被驱散 1 分钟；7 级奉献灵光让你与 10 尺内的友方生物不会被魅惑（18 级扩大至 30 尺）；15 级纯净之魂让你永远处于防护善恶的效应之下；20 级至圣光轮以动作散发半径 30 尺明亮光照与其外 30 尺微光 1 分钟，在其中开始回合的敌对生物受 10 点光耀伤害，且你对抗亡灵或邪魔的法术时豁免具有优势。',
  'subclass-2014-paladin-ancients': 'Oath of the Ancients · PHB · 与精灵一族和德鲁伊教派同样古老的妖精骑士与绿骑士，为守护世间的美与生命而战。3 级获得古贤圣誓法术（捕获打击、动物交谈等）与两种引导神力：自然之怒让 10 尺内一个可见生物以力量或敏捷豁免对抗缠绕的藤蔓，失败则被束缚且每回合结束可重复豁免；驱散无信者迫使 30 尺内能听见圣言的妖精与邪魔进行感知豁免，失败者被驱散 1 分钟并在被掩盖真形时显露原形；7 级守御灵光让你与 10 尺内的友善生物获得对法术伤害的抗性（18 级扩大至 30 尺）；15 级不灭哨卫可在生命值降至 0 且未被直接杀死时改为保留 1 点生命值（每次长休一次），且不受任何衰老减益；20 级上古斗士以动作化身自然伟力 1 分钟，每回合开始恢复 10 点生命值、可用附赠动作施展施法时间为 1 动作的圣武士法术，10 尺内的敌人对抗你的圣武士法术与引导神力时豁免具有劣势。',
  'subclass-2014-paladin-vengeance': 'Oath of Vengeance · PHB · 立誓以一切必要手段惩戒严重罪行的复仇者与黑骑士，宁可牺牲自己的纯洁也要伸张正义。3 级获得复仇圣誓法术（灾祸术、猎人印记等）与两种引导神力：破胆斥喝迫使 60 尺内一个可见生物进行感知豁免（邪魔与亡灵具有劣势），失败则恐慌 1 分钟且速度降为 0，成功则速度减半 1 分钟；仇敌誓言以附赠动作指定 10 尺内一个可见生物，此后 1 分钟你对其发动的攻击检定具有优势，直到它生命值降为 0 或陷入昏迷；7 级坚韧复仇让你在借机攻击命中后立刻移动至多一半速度且不引发借机攻击；15 级复仇之魂可在受仇敌誓言影响的生物发动攻击时以反应对其发动一次近战武器攻击；20 级复仇天使以动作变身 1 小时，背生双翼获得 60 尺飞行速度，并散发 30 尺威胁灵光。',
  'subclass-2014-paladin-crown': 'Oath of the Crown · SCAG · 献身于文明与律法的守护者，效忠民族精神、君王或规则本身。3 级获得王冠圣誓法术（命令术、强制决斗等）与两种引导神力：捍卫挑战以附赠动作迫使 30 尺内任意数量可见生物进行感知豁免，失败者不能自愿离开你周围 30 尺；扭转局势以附赠动作让 30 尺内生命值在一半以下、能听见你说话的选定生物恢复 1d6＋魅力调整值 点生命值（至少 1 点）；7 级神圣誓忠可在 5 尺内生物受到伤害时以反应代替其承受该次伤害，且该伤害无法被任何方式减免；15 级顽强精神在避免麻痹与震慑的豁免检定上具有优势；20 级崇高卫士以动作获得 1 小时增益：对非魔法武器的钝击、穿刺与挥砍伤害具有抗性，30 尺内盟友的死亡豁免与感知豁免具有优势。',
  'subclass-2014-paladin-conquest': 'Oath of Conquest · XGtE · 在战斗中追求荣耀与征服，用恐惧彻底击碎敌人意志的暴君骑士。3 级获得征服圣誓法术（黯冰狱铠、命令术等）与两种引导神力：征服威压以动作迫使 30 尺内由你选择的可见生物进行感知豁免，失败者恐慌你 1 分钟（每回合结束可重复豁免）；导引打击让你在一次攻击检定上获得 +10 加值，可在看到掷骰结果后、公布命中前决定使用；7 级征服灵光在你未失能时向外扩散 10 尺，恐慌于你的生物身处其中时速度降为 0，在其中开始回合还受等于你圣武士等级一半的心灵伤害（18 级扩大至 30 尺）；15 级轻蔑呵斥让命中你的生物受到等于你魅力调整值的心灵伤害（至少 1 点）；20 级不移胜者以动作化身征服 1 分钟，获得所有伤害的抗性、每次攻击动作追加一次攻击，且近战武器攻击掷出 19 或 20 即可重击。',
  'subclass-2014-paladin-redemption': 'Oath of Redemption · XGtE · 相信任何人都可以得到救赎，把仁慈与理解放在暴力之前，只在紧要关头动手。3 级获得救赎圣誓法术（庇护术、睡眠术等）与两种引导神力：和平使节以动作让接下来 10 分钟的魅力（游说）检定获得 +5 加值；斥喝暴力可在 30 尺内敌人以攻击伤害他人后以反应迫使其进行感知豁免，失败则承受与其刚刚造成的伤害等额的光耀伤害，成功减半；7 级护卫灵光允许你以反应代替 10 尺内受伤的生物承受该次伤害，此伤害不会被任何方式减免（18 级扩大至 30 尺）；15 级守护之魂在你未失能且战斗中结束回合时生命值不足上限一半的情况下，恢复 1d6＋圣武士等级一半 点生命值；20 级救赎使节让你对其他生物造成的所有伤害具有抗性，并以攻击伤害你的生物会受到该伤害一半的光耀伤害（被你主动伤害过的生物免疫此效应直到你完成长休）。',
  'subclass-2014-paladin-glory': 'Oath of Glory · TCoE · 坚信自己与同伴注定完成英勇伟业、赢得荣耀，并以刻苦训练为命运的时刻做好准备。3 级获得荣耀圣誓法术（光导箭、英雄气概等）与两种引导神力：绝伦健将以附赠动作获得 10 分钟的力量（运动）与敏捷（特技）检定优势、负重与拖拽重量翻倍、跳远和跳高距离增加 10 尺；鼓舞一击在以至圣斩造成伤害时以附赠动作让 30 尺内由你选择的生物与你自身分配 2d8＋圣武士等级 点临时生命值；7 级迅捷灵光让你的步行速度获得 +10 尺加值，并在 5 尺内盟友回合开始时同样给予 +10 尺（18 级范围增至 10 尺）；15 级辉煌防御以反应为被击中的自己或 10 尺内可见生物提供等于魅力调整值（至少 +1）的 AC 加值，若因此失手且攻击者在触及范围内还可顺势反击（次数等于魅力调整值）；20 级现世传说以附赠动作获得 1 分钟增益：魅力相关检定优势、每回合一次把失手的武器攻击改为命中、以反应重骰失败的豁免。',
  'subclass-2014-paladin-watchers': 'Oath of the Watchers · TCoE · 守望凡人国度，抵御来自其他位面的掠夺与腐化。3 级获得守望圣誓法术（警报术、侦测魔法等）与两种引导神力：守望之志以动作让至多等于魅力调整值数量的 30 尺内可见生物与你共享 1 分钟的智力、感知与魅力豁免优势；驱散异域迫使 30 尺内能听见你祷言的异怪、天族、元素、妖精或邪魔进行感知豁免，失败者被驱散 1 分钟并须尽力远离你；7 级哨卫灵光让你与 10 尺内由你选定的生物在先攻检定上获得等于熟练加值的加值（18 级扩大至 30 尺）；15 级警戒呵斥可在你或 30 尺内可见生物成功通过智力、感知或魅力豁免时以反应对迫使该豁免的生物造成 2d8＋魅力调整值 点力场伤害；20 级尘世壁垒以附赠动作获得 1 分钟增益：120 尺真实视觉、对上述异界生物的攻击检定具有优势，并在命中造成伤害时迫使目标进行魅力豁免，失败的非本位面生物被放逐回原属位面。',

  // ===== 游侠范型（D1 第三批）=====
  'subclass-2014-ranger-hunter': 'Hunter · PHB · 把文明社会与荒野的交界当作战斗岗位，以专业战技应对各种威胁。3 级猎物在巨像屠夫（武器命中生命值不满的目标时追加 1d8 伤害，每回合一次）、巨人杀手（5 尺内大型或更大生物攻击后以反应对其发动攻击）与灭族者（对目标 5 尺内的另一生物追加一次武器攻击）中三选一；7 级防守战术在冲出重围（以你为目标的借机攻击具有劣势）、多重防御（被命中后本回合对抗该敌人的后续攻击 AC +4）与钢铁意志（对抗恐慌的豁免具有优势）中三选一；11 级多重攻击在箭雨（对射程内一点周围 10 尺内任意数量生物各发动一次远程攻击）与剑刃风暴（对身边 5 尺内任意数量生物各发动一次近战攻击）中二选一；15 级高效猎人防术在反射闪避、逆流而上与直觉闪避中三选一。',
  'subclass-2014-ranger-beast-master': 'Beast Master · PHB · 体现文明种族与野兽之间的友谊，与一头训练有素的动物伴侣协同作战。3 级游侠伴侣指定一头体型不超过中型、挑战等级 1/4 或更低的野兽，把熟练加值加到它的 AC、攻击检定、伤害掷骰与具有熟练项的豁免和技能检定上，其生命值上限取原上限与你游侠等级四倍中的较高者，它随你的先攻行动并听从声音指令（你也可以在命令它攻击的同时自己发动一次武器攻击），它死亡后可花 8 小时与另一头野兽建立联结；7 级特殊训练让未曾攻击的野兽可用附赠动作被命令执行疾走、撤离或协助，且其攻击视为魔法；11 级兽性狂怒让被命令攻击的野兽发动两次攻击，或使用其多重攻击动作项；15 级法术共享让你施展的目标为自身的法术同时作用于 30 尺内的野兽伴侣。',
  'subclass-2014-ranger-gloom-stalker': 'Gloom Stalker · XGtE · 以至暗之地为家，驾驭堕影冥界的魔法猎杀潜伏在黑暗中的敌人。3 级恐惧伏击在每场战斗第一个回合开始时让移动速度增加 10 尺，武器命中可追加 2d6 心灵伤害（每回合一次，次数等于感知调整值，长休恢复），并在先攻检定中加入感知调整值，同时始终准备易容术等幽域追猎者法术；3 级阴影视野获得 60 尺黑暗视觉（已有则再增加 60 尺），完全身处黑暗时对依靠黑暗视觉观察你的生物视为隐形；7 级钢铁意志获得感知豁免熟练（已有则改选智力或魅力豁免）；11 级追猎如风把恐惧打击提升为 2d8，并可选瞬杀（对原目标 5 尺内另一生物再发动一次攻击）或群慌（目标与其 10 尺内生物感知豁免失败则恐慌至你下回合开始）；15 级如影随行以反应给攻击你的检定施加劣势，之后还能传送至 30 尺内可见的未占据空间。',
  'subclass-2014-ranger-horizon-walker': 'Horizon Walker · XGtE · 守护世界免受其他位面的威胁，为追猎敌人而穿梭于位面之间。3 级获得边界行者法术（防护善恶、迷踪步等），侦测传送门以动作感知 1 里内最近的位面传送门的方向与距离（每次短休或长休一次），位面战士以附赠动作指定 30 尺内一个可见生物，本回合你对其下一次武器攻击造成力场伤害并追加 1d8（11 级 2d8）；7 级以太漫步以附赠动作无需法术位施展以太化，该法术在你本回合结束时结束（每次短休或长休一次）；11 级闪现打击让你在攻击动作中每次攻击前传送 10 尺，若攻击了至少两个不同生物还可额外攻击第三个生物；15 级灵体防御以反应获得该次攻击所含全部伤害类型的抗性直到当前回合结束。',
  'subclass-2014-ranger-monster-slayer': 'Monster Slayer · XGtE · 专注猎杀黑夜中的怪物与邪恶魔法使用者，以超自然技巧破解强敌。3 级获得怪物杀手魔法（防护善恶、诚实之域等），猎手感知以动作观察 60 尺内一个可见生物并立刻得知其伤害免疫、抗性与易伤（次数等于感知调整值，长休恢复），狩猎开始以附赠动作指定 60 尺内一个可见生物，此后每回合首次以武器命中该目标时追加 1d6 同类型伤害，直到你完成短休或长休；7 级卓越防守在被该目标迫使豁免，或为挣脱其擒抱而进行技能检定时可掷 1d6 加入结果；11 级魔法使的克星可在 60 尺内生物施展法术或传送时以反应迫使其感知豁免，失败则法术或传送失败并被浪费（每次短休或长休一次）；15 级杀手反制在该目标迫使你豁免时于豁免前以反应对其发动一次武器攻击，命中则本次豁免自动成功。',
  'subclass-2014-ranger-fey-wanderer': 'Fey Wanderer · TCoE · 因一次奇遇而被妖精魔力缠绕，同时代表凡间与妖精国度的游侠。3 级获得妖精漫游者法术（魅惑类人、迷踪步等），哀惧灵袭在用武器命中生物时追加 1d4 心灵伤害（每个生物每回合只能受到一次，11 级提升为 1d6），妖冶娴都让每次魅力检定获得等于感知调整值的加值（至少 +1）并获得欺瞒、表演或游说之一的熟练；7 级妖思魅缕让你对抗魅惑与恐慌的豁免具有优势，并在你或 120 尺内可见生物成功通过此类豁免时以反应迫使 120 尺内另一个可见生物进行感知豁免，失败则被你魅惑或对你恐慌 1 分钟（每回合结束可重复豁免）；11 级精宸所与习得妖精召唤术（不计入已知游侠法术、无需材料成分，可免费施展一次，也可改为无需专注并只持续 1 分钟）；15 级雾行漫游可免费施展迷踪步，次数等于感知调整值，并可携带 5 尺内一名可见的自愿生物一同传送。',
  'subclass-2014-ranger-swarmkeeper': 'Swarmkeeper · TCoE · 与自然精魂形成的集群羁绊共生，让集群成为战斗中的帮手。3 级蜂聚集群让集群常驻你的空间，每回合一次在攻击命中后选择：让集群追加 1d6 穿刺伤害、迫使目标力量豁免失败则被水平移动至多 15 尺，或让你自己被水平移动 5 尺，同时获得集群牧者法术（妖火、法师之手等）；7 级翻腾浪涌以附赠动作获得 10 尺飞行速度与悬浮 1 分钟（次数等于熟练加值，长休恢复）；11 级壮大集群把集群伤害提升为 1d8，被移动的目标豁免失败还会倒地，你被移动后获得半身掩护直到下回合开始；15 级群逸逃散在受到伤害时以反应获得该次伤害的抗性，并消失于集群中传送到 30 尺内一个未被占据的可见空间（次数等于熟练加值）。',
  'subclass-2014-ranger-drakewarden': 'Drakewarden · FTD · 与一条龙族精魄联结，让精魄化形为随你一同成长的龙兽并共享龙族力量。3 级龙族赠礼习得戏法奇术（视为游侠法术）并学会龙语或其他一门语言，龙兽伙伴以动作在 30 尺内召唤龙兽（与你共享先攻、在你的回合后立刻行动，需附赠动作下达指令，长休后可再次召唤或消耗 1 环以上法术位）；7 级牙鳞之联让龙兽长出翅膀并获得与步行速度相等的飞行速度、成长为中型且可被你骑乘（骑乘时不能使用该飞行速度），其啃咬追加一颗与龙族精粹同类型的 d6 伤害，你也获得该伤害类型的抗性；11 级龙兽吐息以动作喷吐 30 尺锥形吐息（起点也可设为龙兽），敏捷豁免失败受 8d6 所选类型伤害、成功减半（15 级提升为 10d6，长休一次或消耗 3 环以上法术位）；15 级完美联结让龙兽的追加伤害累计为 2d6、成长为大型且骑乘时可飞行，并在你与龙兽相距 30 尺内时以反应为其中一方提供对该次伤害的抗性（次数等于熟练加值）。',

  // ===== 游荡者范型（D1 第三批）=====
  'subclass-2014-rogue-thief': 'Thief · PHB · 专注盗窃技艺的窃贼、强盗与寻宝者，兼修探索废墟、解读罕见语言与使用魔法物品的本领。3 级快手允许用灵巧动作的附赠动作进行敏捷（巧手）检定、以盗贼工具解除陷阱或撬锁，或执行使用物件动作，梁上君子让攀爬不再消耗额外移动力，有助跑的跳远距离增加等于敏捷调整值的尺数；9 级极效潜行在回合内移动不超过自身速度一半时让敏捷（隐匿）检定具有优势；13 级使用魔法装置让你使用魔法物品时忽略所有职业、种族与等级限制；17 级窃盗本能让你在战斗第一轮以正常先攻行动后，再以先攻减 10 的数值额外行动一回合（遭受突袭时不能使用）。',
  'subclass-2014-rogue-assassin': 'Assassin · PHB · 专注残忍冷酷的死亡艺术，以隐匿、下毒与易容铲除目标。3 级附赠熟练获得易容工具与制毒者工具熟练，暗杀让对战斗开始后尚未行动过的生物发动的攻击检定具有优势，且命中被突袭的生物时该次攻击视为掷出了重击；9 级专业渗透可花 7 天与 25 gp 为自己编造一个不存在的身份（不能伪造成已存在的角色），此后凭易容使用该身份时其他生物会相信你是那个人；13 级冒充者花至少 3 小时学习目标的说话、写字与行为即可准确模仿，机警生物起疑时你为避免被识破的魅力（欺瞒）检定具有优势；17 级致命一击命中被突袭的生物时迫使其体质豁免（DC 为 8＋敏捷调整值＋熟练加值），失败则本次攻击造成双倍伤害。',
  'subclass-2014-rogue-arcane-trickster': 'Arcane Trickster · PHB · 以幻术与惑控系的诡术强化本已老练的隐匿和灵动，用智力施展法师法术。3 级施法学会 3 个法师戏法（含法师之手）与 3 个 1 环法师法术（其中两个须来自惑控系与幻术系），10 级再添一个戏法，8／14／20 级可学习任意学派的法术；3 级法师之手诈术让幽灵手隐形，可把物件放入或取出他人携带的容器，并以其在施法范围内用盗贼工具撬锁与解除陷阱，也可用灵巧动作的附赠动作控制它；9 级诡术伏击让你在躲藏状态下对生物施法时，该生物本回合对抗该法术的豁免具有劣势；13 级万能诡术以附赠动作指定幽灵手 5 尺内一个生物，直到本回合结束你对其攻击检定具有优势；17 级法术窃贼可在法术以你为目标时以反应迫使施法者以其施法属性豁免，失败则取消该法术对你的效应，若其环阶在你可施展范围内还能盗取该法术的知识 8 小时。',
  'subclass-2014-rogue-mastermind': 'Mastermind · XGtE · 以言语为匕首与毒药，专注影响他人并掌握其秘密的间谍与阴谋家。3 级谋陷大师获得易容工具、文书伪造工具与一种赌博工具熟练以及两门自选语言，听过一个生物讲话 1 分钟且懂得其语言即可准确模仿其语气与口音；3 级战术大师可以附赠动作执行协助动作，且协助盟友攻击时目标可位于 30 尺内而非 5 尺内（前提是目标能看见或听见你）；9 级帷幄之士在战斗之外观察或与其他生物交互至少 1 分钟后，可由地下城主告知其智力、感知、魅力或职业等级中两项与你相比的高低；13 级误导可在你被选为攻击目标且 5 尺内有生物为你提供掩护时以反应把该攻击转嫁到掩护者身上；17 级瞒天之魂让你的思想无法被心灵感应或其他能力读取，并可用魅力（欺瞒）对抗读心者的感知（洞悉）以喂给对方虚假思想。',
  'subclass-2014-rogue-swashbuckler': 'Swashbuckler · XGtE · 兼顾速度、优雅与魅力的一对一剑术，战斗姿态更接近表演。3 级梦幻舞步让你在回合内对某生物发动近战攻击后，它在本回合剩余时间无法对你发动借机攻击；3 级潇洒无畏让你把魅力调整值加入先攻检定，并在目标 5 尺内没有其他生物、你 5 尺内也没有其他生物且攻击检定没有劣势时，无需优势即可对其发动偷袭；9 级潇洒气质以动作进行一次魅力（游说）对抗目标感知（洞悉）的检定，成功且目标敌对时它对除你之外的目标攻击具有劣势且不能对其借机攻击 1 分钟，目标非敌对时则被你魅惑 1 分钟；13 级优雅战技以附赠动作让本回合下一次敏捷（特技）或力量（运动）检定具有优势；17 级决斗大师在攻击失手时以优势重投该次攻击检定（每次短休或长休一次）。',
  'subclass-2014-rogue-inquisitive': 'Inquisitive · XGtE · 精于揭开秘密与谜团，用锐利双眼寻找细节并读出他人的言辞与表情。3 级辨谎之耳在察觉生物是否说谎的感知（洞悉）检定中把 d20 掷出的 7 或更低视为 8，鉴识之眼可用附赠动作进行感知（察觉）检定以侦测隐藏的生物或物体，或进行智力（调查）检定以揭示和破译线索；3 级战术洞悉以附赠动作对 30 尺内一个可见且未失能的生物进行感知（洞悉）对抗其魅力（欺瞒），成功后即使没有优势也能对其发动偷袭 1 分钟（攻击检定具有劣势时仍然不行）；9 级目不转睛在回合内移动不超过速度一半时让感知（察觉）与智力（调查）检定具有优势；13 级明察秋毫以动作感知 30 尺内的幻术、变形生物与其他欺瞒感官的魔法（次数等于感知调整值，长休恢复）；17 级伺隙锐瞳在战术洞悉生效期间对被洞悉生物造成的偷袭伤害提高 3d6。',
  'subclass-2014-rogue-scout': 'Scout · XGtE · 擅长在远离城市与街道处潜行和生存，充当队伍带头侦查的眼睛与耳朵。3 级散兵战术可在 5 尺内的敌人结束其回合时以反应移动至多一半速度且不引发借机攻击，生存专家获得自然与求生技能熟练，并在使用这两项熟练的任何属性检定中加入双倍熟练加值；9 级优异灵活让步行速度获得 +10 尺加值，若已有攀爬或游泳速度也一并增加；13 级伏击大师让先攻检定具有优势，且战斗中第一轮被你击中的生物直到你下回合开始前被攻击时具有优势；17 级瞬息打击在攻击动作后以附赠动作追加一次攻击，即使本回合已用过偷袭该次攻击也能受益，但同一回合不能对同一目标偷袭两次。',
  'subclass-2014-rogue-phantom': 'Phantom · TCoE · 徘徊于生死之间，浸淫负能量并从死者处获取知识，最终变得如同幽灵。3 级亡者余声在每次短休或长休后选择一项你缺乏熟练的技能或工具并获得其熟练（更换时失去原先那项），墓穴惊嚎在造成偷袭伤害后让该生物 30 尺内第二个可见生物受一次暗蚀伤害，掷一半数量的偷袭骰（向上取整）并以结果之和作为伤害（次数等于熟练加值，长休恢复）；9 级逝者遗物可在 30 尺内可见生物死亡时以反应张开一只空闲的手造出微型魂器（至多同时持有熟练加值枚），随身携带时死亡豁免与体质豁免具有优势，也可销毁魂器免费再次使用墓穴惊嚎，或以动作向相关灵魂提一个它生前所知的问题；13 级幽灵漫步以附赠动作化为灵体形态 10 分钟，获得 10 尺飞行速度、能悬浮且以你为目标的攻击检定具有劣势，可如困难地形般穿过生物或物品（若回合结束时仍在其位置则受 1d10 力场伤害）；17 级死亡之友让墓穴惊嚎可同时对攻击目标与第二目标造成该暗蚀伤害，并在长休结束时若你没有魂器则自动获得一枚。',
  'subclass-2014-rogue-soulknife': 'Soulknife · TCoE · 以心灵的力量攻击与渗透，用灵能击穿物理与心灵的障碍。3 级灵能力量提供等于两倍熟练加值的 d6 灵能骰（5 级 d8、11 级 d10、17 级 d12，长休全恢复，并可用附赠动作回复一枚但每次休息限一次），灵振诀窍在具有熟练的技能或工具检定失败时掷灵能骰加入结果（仅在因此成功时消耗该骰），心灵低语以动作让至多等于熟练加值数量的可见生物与你建立最长 1 里的心灵感应交流（每次长休后免费使用一次，否则消耗灵能骰）；3 级心灵之刃可用空闲的手塑造灵能刀刃（简易近战武器，具有灵巧与投掷属性，常规射程 60 尺且无最大射程，命中造成 1d6＋所用属性调整值 的心灵伤害，攻击后立即消失），同一回合还可用附赠动作在另一只空闲手中塑造第二把并追加一次攻击（伤害骰为 1d4）；9 级灵魂之刃让念刃失手时掷灵能骰加入该次攻击检定，或以附赠动作消耗一枚灵能骰把念刃掷出并传送到至多骰值十倍尺数的可见未占据空间；13 级心灵面纱以动作连同穿着与携带物隐形至多 1 小时（长休一次，也可消耗灵能骰再用）；17 级撕裂心智在念刃造成偷袭伤害时迫使目标感知豁免（DC 为 8＋熟练加值＋敏捷调整值），失败则震慑至多 1 分钟（每回合结束可重复豁免）。',

  // ===== 术士术法起源（D1 第三批）=====
  'subclass-2014-sorcerer-draconic-bloodline': 'Draconic Bloodline · PHB · 天赋魔法源于龙族魔力，巨龙先祖的血统刻在血液与身体之中。1 级巨龙先祖选定一种巨龙并确定对应的伤害类型、习得龙语，与巨龙互动时的魅力检定可使用双倍熟练加值，龙族体魄让生命值上限随每个术士等级 +1，且未着装护甲时 AC 等于 13＋敏捷调整值；6 级元素亲和让造成先祖对应伤害类型的法术在其中一次伤害掷骰上加上魅力调整值，并可花 1 术法点获得 1 小时对应伤害类型的抗性；14 级龙翼以附赠动作从背后张开龙翼，获得等于当前速度的飞行速度（着装未特殊设计的护甲时无法张开）；18 级真龙姿态以动作与 5 术法点张开 60 尺的震撼或恐惧灵光 1 分钟，在灵光内开始回合的敌对生物感知豁免失败即被魅惑或恐慌，成功则在 24 小时内免疫该灵光。',
  'subclass-2014-sorcerer-wild-magic': 'Wild Magic · PHB · 天生魔力来自与创生秩序相生相对的混沌狂野力量，随时等待释放。1 级狂野魔法浪涌在你施展不低于 1 环的术士法术后由地下城主决定是否骰 d20，掷出 1 即按 d100 表产生随机魔法效应（每回合至多一次，无需专注且不受超魔法影响），混乱之潮可让一次攻击检定、属性检定或豁免检定具有优势（用后须长休才能恢复，恢复前施法有可能触发浪涌）；6 级扭曲幸运以反应消耗 2 术法点，把 1d4 的结果作为加值或减值加到 60 尺内一个可见生物的检定上；14 级操控混沌让你每次骰狂野魔法浪涌时骰两次并自选其一生效；18 级法术轰击在法术伤害掷骰中出现最大值时，可挑选其中一粒再骰一次并把结果加入伤害（每回合一次）。',
  'subclass-2014-sorcerer-storm-sorcery': 'Storm Sorcery · XGtE · 内在魔法源于气元素之力，风暴早已浸透灵魂。1 级风语者让你能说读写原初语并理解水族语、气族语、火族语与土族语的使用者，暴风魔法让你在回合内施展 1 环或更高环阶法术后，立刻以附赠动作飞行至多 10 尺且不引发借机攻击；6 级风暴之心获得闪电与雷鸣伤害抗性，并在开始施展能造成这两类伤害的法术时让 10 尺内由你选择的可见生物受等于术士等级一半的闪电或雷鸣伤害，风暴导向可以动作让 20 尺半径球状区域内停止下雨，或以附赠动作控制身边 100 尺内的风向；14 级暴风狂怒在被近战攻击命中时以反应对攻击者造成等于术士等级的闪电伤害并迫使其力量豁免，失败则被直线推开至多 20 尺；18 级清风之灵免疫闪电与雷鸣伤害并获得 60 尺魔法飞行速度，还能以动作把飞行速度降为 30 尺，让 30 尺内至多 3＋魅力调整值 个生物获得 30 尺飞行速度 1 小时。',
  'subclass-2014-sorcerer-divine-soul': 'Divine Soul · XGtE · 灵魂中闪耀着一点神力火花，让术士的奥术与神术彼此交融。1 级神圣魔法让你学习或替换法术时可从术士与牧师两个法术列表中选择，并按善良、邪恶、守序、混乱或中立亲和力额外获得一个不计入已知上限的术士法术（如疗伤术、致伤术、祝福术），众神眷恩在豁免检定失败或攻击检定失手时掷 2d4 并把结果加入该检定（每次短休或长休一次）；6 级强效治疗以 1 术法点让你或 5 尺内盟友为重定治疗量而重骰任意数量枚骰子（每回合一次）；14 级异界光翼以附赠动作从背后张开光翼，获得 30 尺飞行速度，外观按所选亲和力呈雄鹰、蝙蝠或蜻蜓之翅；18 级神赐痊愈在生命值不足一半时以附赠动作立刻恢复等于生命值上限一半的生命值（每次长休一次）。',
  'subclass-2014-sorcerer-shadow-magic': 'Shadow Magic · XGtE · 内在魔力来自堕影冥界本身，肉身因此蒙上一层怪异的柩衣。1 级幽暗之瞳获得 120 尺黑暗视觉（3 级起还习得不计入已知上限的黑暗术，并可用 2 点术法点或一枚法术位施展，以术法点施展时能看穿该法术造出的黑暗），终焉之力在生命值被降至 0 时以魅力豁免（DC 为 5＋该次所受伤害）改为保留 1 点生命值，但光耀伤害造成的归零或重击无法如此规避（成功后须长休才能再用）；6 级凶兆猎犬以附赠动作消耗 3 点术法点，在 120 尺内选定生物周围 30 尺召出使用恐狼数据的凶兆猎犬（获得等于术士等级一半的临时生命值，只沿最短路径追击指定猎物，在其 5 尺内猎物对抗你法术的豁免具有劣势，持续 5 分钟）；14 级幽影漫步在微光或黑暗中以附赠动作传送至多 120 尺至另一处微光或黑暗空间；18 级幽暗之形以附赠动作消耗 6 点术法点变身 1 分钟，获得除力场与光耀外所有伤害类型的抗性，并能如穿越困难地形般穿过生物与物件。',
  'subclass-2014-sorcerer-aberrant-mind': 'Aberrant Mind · TCoE · 意识曾被异界影响以卷须缠绕，灵能力量从此在心灵中燃烧。1 级灵能法术让心灵之楔、哈达之臂等法术始终准备，传心谈话以附赠动作与 30 尺内一个可见生物建立心灵感应链接，持续等于术士等级的分钟数，交流距离不超过魅力调整值里数（至少 1 里）；6 级灵能术法可将灵能法术改以等于该法术环数的术法点施展，并忽略言语、姿势与不消耗且未标价的材料成分，心灵防御获得心灵伤害抗性以及避免和结束魅惑与恐慌状态的豁免优势；14 级血肉启示以附赠动作消耗 1 点以上术法点变形 10 分钟，每点术法点可换得一项效应（两倍行走速度的游泳速度与水下呼吸、等于速度的飞行与悬浮、60 尺内识破隐形、穿过最窄 1 寸的缝隙并以 5 尺移动力脱离束缚或受擒）；18 级扭曲内爆以魔法动作传送到 120 尺内可见的未占据位置，并迫使原位置 30 尺内生物力量豁免，失败受 3d10 力场伤害并被拉向原位（长休一次，也可花 5 术法点重置）。',
  'subclass-2014-sorcerer-clockwork-soul': 'Clockwork Soul · TCoE · 源自机械境等绝对秩序位面的力量扩散进灵魂，让你成为一个宏伟系统的一部分。1 级时械法术让防护善恶、警报术、次等复原术等法术始终准备，归复平衡以反应让 60 尺内一个可见生物即将进行的检定免受优势或劣势影响（次数等于魅力调整值，长休恢复）；6 级律令之壁以魔法动作消耗 1 至 5 点术法点，为自身或 30 尺内一个可见生物造出具有等量 d8 的屏障，被守护者受伤时可消耗任意数量骰子并按结果之和减少伤害，屏障持续到长休或你再次使用该特性；14 级序列意识以附赠动作进入 1 分钟状态，针对你的攻击检定不受优势影响，且你每次 d20 检定可把掷出的 9 或更低视为 10（长休一次，也可花 5 术法点重置）；18 级时械矩阵以魔法动作在以你为源点的 30 尺立方内召出精魂，合计治疗至多 100 点生命值由你分配、修复损坏物件，并结束范围内生物或物件承受的六环及以下法术（长休一次，也可花 7 术法点恢复）。',
  'subclass-2014-sorcerer-lunar-sorcery': 'Lunar Sorcery · DSotDQ · 曾暴露于世界月亮的集中魔力之下，被灌注月之魔法。1 级月之化身按满月、朔月与新月三张月之法术表获得不计入已知上限的额外法术，并在每次长休后选择展现的月相，可不消耗法术位施展对应月相的一个 1 环法术（长休前仅一次），月火让你习得圣火术并可在施放时改为选择 5 尺内两个生物为目标；6 级月之恩泽让与当前月相相关联的学派（满月为防护与预言、朔月为惑控与死灵、新月为幻术与变化）的法术在使用超魔法时少花 1 点术法点（次数等于熟练加值，长休恢复），阴晴圆缺以附赠动作消耗 1 术法点转换为另一种月相；14 级月之赋能按当前月相提供 10 尺明亮光照与调查、察觉检定优势（满月）、隐匿检定优势且完全处于黑暗中时受攻击具有劣势（朔月），或暗蚀与光耀伤害抗性（新月）；18 级月之异象以附赠动作激发当前月相之力，分别造成 30 尺内选定生物目盲与 3d8 治疗、3d10 暗蚀伤害与速度归零且自身隐形，或传送并让自己与同伴获得所有伤害抗性（长休前再次使用需 5 术法点）。',

  // ===== 法师奥术传承（D1 第三批）=====
  'subclass-2014-wizard-abjuration': 'School of Abjuration · PHB · 以阻碍、驱逐与保护为使命的护法师，在祛除恶灵、隔绝探测与关闭传送门时体现价值。2 级防护学者让抄写防护系法术的时间与金钱花费减半，奥术守御在你施展 1 环或更高环阶防护系法术时用其魔力造出护身结界，其生命值上限为两倍法师等级＋智力调整值并替你承受伤害（每次施展 1 环以上防护系法术可按两倍法术环阶恢复其生命值，长休后才能重新创造）；6 级投射守御可在 30 尺内一个可见生物受伤时以反应让奥术守御替其吸收伤害，守御降到 0 后剩余伤害仍由被保护者承受；10 级精通防护让你在法术反制、解除魔法等需要施法属性检定的防护系法术上加上熟练加值；14 级法术抗性让你对抗法术的豁免检定具有优势，并对法术造成的伤害具有抗性。',
  'subclass-2014-wizard-conjuration': 'School of Conjuration · PHB · 偏爱凭空创造物件与生物，并精于传送甚至跨越位面的咒法师。2 级咒法学者让抄写咒法系法术的时间与金钱花费减半，次级咒术以动作咒唤一件非活化物件（每边不超过 3 尺、重量不超过 10 磅，形状须是你见过的非魔法物件，散发 5 尺微光，1 小时后消失，再次使用、受到伤害或造成伤害时提前消失）；6 级王车易位以动作传送至多 30 尺至一处可见的未占据空间，也可指定传送距离内一个自愿的小型或中型生物并与之互换位置（须完成长休或施展 1 环以上咒法系法术才能再次使用）；10 级咒法专注让你在专注咒法系法术期间不会因承受伤害而被打断；14 级强韧召唤让被你用咒法系法术召唤或创造的生物获得 30 点临时生命值。',
  'subclass-2014-wizard-divination': 'School of Divination · PHB · 揭开时空与意识的面纱，以鉴别、远视、超自然学识与预知指点他人。2 级预言学者让抄写预言系法术的时间与金钱花费减半，预兆让你在每次长休时投两次 d20 并记下骰值，用以替换你或你能看见的生物的一次攻击检定、豁免检定或属性检定（须在检定开始前决定，每回合一次，每个预知骰只能用一次）；6 级预言专家在以法术位施展 2 环或更高环阶的预言系法术时恢复一个已消耗的法术位，其环阶须低于该法术且不高于 5 环；10 级天眼通以动作选择获得 60 尺黑暗视觉、60 尺以太视界、读懂任何语言，或看见 10 尺内处于你视线中的隐形生物与物件，直到你失能或开始休息（每次休息后才能再次使用）；14 级高等预兆让预兆每次长休投三枚 d20 而非两枚。',
  'subclass-2014-wizard-enchantment': 'School of Enchantment · PHB · 磨练以魔法迷引或骗诱他人与怪物的技艺，既可令暴力者放下武器，也可强制他人服从。2 级惑控学者让抄写惑控系法术的时间与金钱花费减半，催眠凝视以动作指定 5 尺内一个能看见你或听见你的生物，其感知豁免失败即被你魅惑、速度降为 0 并陷入失能直到你下回合结束，你可用后续动作延续该效应（目标移出 5 尺、看不见也听不见你或受到伤害时提前终止，效应终止或该生物首次豁免成功后，直到你完成长休前都不能再对它使用）；6 级直觉魅惑可在 30 尺内一个可见生物攻击你时以反应偏转该攻击，前提是攻击范围内另有生物，攻击者感知豁免失败则改为攻击距其最近的生物（免疫魅惑的生物免疫此特性）；10 级分裂惑控让以单一生物为目标的 1 环或更高环阶惑控系法术可以指定第二个目标；14 级编演记忆可改变某个生物的认识使其无法察觉自己已被魅惑，并能以动作尝试修改其记忆，其智力豁免失败则失去 1＋魅力调整值 小时的记忆。',
  'subclass-2014-wizard-evocation': 'School of Evocation · PHB · 以魔力创造苦寒、灼焰、惊雷、汲电与烈酸等元素威能，常被军队雇为远距离轰炸的重炮手。2 级塑能学者让抄写塑能系法术的时间与金钱花费减半，法术塑形让你施展塑能系法术时指定 1＋该法术环阶 个你能看见的生物，使其豁免直接判为成功，且豁免成功伤害减半的法术对其完全不造成伤害；6 级强力戏法让生物即使成功通过对抗你伤害性戏法的豁免也仍受一半伤害，但不受戏法的其他效应影响；10 级强效塑能让你把智力调整值加到任何由你施展的法师塑能法术的其中一次伤害掷骰中；14 级超限导能可让一个造成伤害的 1 至 5 环法师法术伤害直接取最大值（不能用于戏法），首次使用无任何减益，此后在长休前每再用一次就使每环阶的 2d12 暗蚀反噬再加 1d12，且该反噬无视抗性与免疫。',
  'subclass-2014-wizard-illusion': 'School of Illusion · PHB · 用魔法扰乱感官、迷惑意识，以细微却奥妙的幻象欺诈最具智慧的人。2 级幻术学者让抄写幻术系法术的时间与金钱花费减半，精通次级幻象让你习得次级幻象戏法（已学会则改学另一个自选法师戏法，且不计入已知戏法数目），并可一次施法同时造出声音与影像；6 级易变幻象让你在施展持续时间不少于 1 分钟的幻术系法术时以动作改变幻象外形（仍须遵守该法术的描述且你能看见该幻象）；10 级幻影化形可在生物对你发动攻击检定时以反应在攻击者与你之间插入自身的幻象分身，使该次攻击直接判为未命中，分身随即消失（每次短休或长休一次）；14 级亦真亦幻让你施展 1 环或更高环阶幻术系法术时，以附赠动作让幻象中一个非活化的非魔法物件化作真实 1 分钟，但该物件无法造成伤害。',
  'subclass-2014-wizard-necromancy': 'School of Necromancy · PHB · 探索宇宙中的生命、死亡与亡灵之力，在摧毁敌人肉体的同时汲取其生命能量。2 级死灵学者让抄写死灵系法术的时间与金钱花费减半，惧怖收割每回合一次在以 1 环或更高环阶法术杀死一个或多个生物时恢复生命值，数值为法术环阶的两倍（若为死灵系法术则为三倍），但杀死亡灵或构装生物时无法获益；6 级不死奴仆把活化死尸加入法术书，施展时可额外创造一具丧尸或骷髅，且你用死灵系法术创造的亡灵生命值上限增加等于你法师等级的数值、武器伤害掷骰加上你的熟练加值；10 级不死适应让你对暗蚀伤害具有抗性，且生命值上限无法被降低；14 级命令亡灵以动作指定 60 尺内一个可见亡灵，其魅力豁免失败即变为对你友善并服从你的命令，智力不低于 8 者进行该豁免时具有优势，智力不低于 12 者即使失败也可每小时重掷豁免。',
  'subclass-2014-wizard-transmutation': 'School of Transmutation · PHB · 研习改变物质与能量的法术，把魔法当作铸造现实的工具。2 级变化学者让抄写变化系法术的时间与金钱花费减半，次级炼金每花 10 分钟即可转化 1 立方尺由木材、石头（不含宝石）、钢铁、铜或白银制成的非魔法物件，把它变成上述材质中的另一种（1 小时后或专注中断时复原）；6 级变化师之石花 8 小时造出一颗石头，持有者可选 60 尺黑暗视觉、未重载时速度 +10 尺、体质豁免熟练，或对强酸、寒冷、闪电、火焰、雷鸣之一的伤害抗性，你自行持有时每施展一个 1 环或更高环阶变化系法术都可更换该效应；10 级变形生物把变形术加入法术书，并可无需法术位对自身施展该法术变成挑战等级不高于 1 的野兽（每次短休或长休一次）；14 级变化宗师以动作耗尽变化师之石，实现高等转化（把不大于 5 尺立方的非魔法物件变为体积质量相近、价值等同或更低的另一件）、万灵秘药（移除所有诅咒、疾病与毒素并恢复全部生命值）、起死回生（无需法术位施展死者复活）或返老还童（使自愿生物外表年龄减少 3d10 年，最多减至 13 岁）。',
  'subclass-2014-wizard-bladesinging': 'Bladesinging · TCoE · 把剑术与舞蹈结合的精灵奥法传承，以纷繁优雅的武技偏转攻击并引导魔法。2 级战歌训练获得轻甲熟练、一把自选的单手近战武器熟练，以及表演技能熟练，剑歌以附赠动作唤起 1 分钟（前提是未着装中甲与重甲、未使用盾牌），期间 AC 获得等于智力调整值（至少 +1）的加值、步行速度 +10 尺、敏捷（特技）检定具有优势，且维持法术专注的体质豁免获得等于智力调整值（至少 +1）的加值，次数等于熟练加值（长休恢复，失能、着装中甲重甲或盾牌、双手并用一把武器攻击时提前结束）；6 级额外攻击让攻击动作可发动两次攻击，并可把其中一次替换为施展一个戏法；10 级守御之歌在剑歌期间受到伤害时以反应消耗一枚法术位，使所受伤害减少该法术位环阶的五倍；14 级胜利之歌让你在剑歌期间把智力调整值（至少 +1）加到近战武器伤害上。',
  'subclass-2014-wizard-war-magic': 'War Magic · XGtE · 融合塑能与防护的机理，把魔法视为比钢铁更坚韧的武器与盔甲。2 级奥术偏斜可在被攻击命中或豁免失败时以反应让对抗该攻击的 AC 获得 +2 加值或该豁免获得 +4 加值，但直到你下回合结束前都不能施展戏法之外的法术，战术之智让你在先攻检定中获得等于智力调整值的加值；6 级魔力潮涌可储存至多等于智力调整值（至少 1 股）的潮涌，长休后数量变回 1 股，以解除魔法或法术反制终止或打断法术时可窃得 1 股，在没有潮涌时完成短休也能获得 1 股，每回合一次在你以法师法术对生物或物件造成伤害时消耗 1 股，追加等于法师等级一半的力场伤害；10 级耐久魔法让你在专注一个法术期间 AC 与任何豁免检定获得 +2 加值；14 级偏斜罩幕让你使用奥术偏斜时令魔法能量涌出，选择至多三个 60 尺内可见目标各受等于法师等级一半的力场伤害。',
  'subclass-2014-wizard-order-of-scribes': 'Order of Scribes · TCoE · 与书卷联系最紧密的法师群体，用魔法唤醒法术书，让书卷成为值得信赖的伙伴。2 级法师之笔以附赠动作在空着的手中造出一支微型魔法羽毛笔，它无需墨水即可自行生墨、抄录法术每个法术等级只需 2 分钟，并能以附赠动作消除 5 尺内自己写下的文字；2 级觉醒魔典让法术书可作为施展法师法术的法器，当你消耗法术位施展法师法术时可把伤害类型临时替换为书中另一个同环阶法术的伤害类型，并能以正常施法时间进行仪式施法而非额外多花 10 分钟（该好处每次长休一次），还可在短休时用羽毛笔把书中意识转移到新书；6 级神识显现以附赠动作让书中意识化作微型灵体物件（无形、不占空间、散发 10 尺微光、能用心灵感应分享所见所闻），你每回合施放法师法术时可改用它的感官与所在空间施法（次数等于熟练加值，长休恢复），它可穿过生物但不能穿过物件，距你超过 300 尺、被解除魔法或被驱散时消失；10 级书士宗师在每次长休后用魔法羽毛笔把书中一个 1 或 2 环、施法时间为 1 动作的法术抄成卷轴，卷轴中的法术视为高 1 环阶且只有你能读懂，你制造卷轴所需的时间与金钱减半；14 级书人合一带书时智力（奥秘）检定具有优势，并在显现的意识受到伤害时以反应将其驱散以免除全部伤害，代价是法术书暂时失去环阶之和不少于 3d6 骰值的自选法术，须经 1d6 次长休后才能恢复。',
  'subclass-2014-wizard-chronurgy': 'Chronurgy Magic · EGtW · 追随时间使传承的法师专注操纵时间，按自己的意愿改写现实的流动。2 级时间变幻可在你或 30 尺内可见生物进行攻击检定、属性检定或豁免检定后以反应迫使其重骰并使用第二次结果（得知检定是否成功后仍可决定，可用两次，长休恢复），时序感知让你在先攻检定中获得等于智力调整值的加值；6 级瞬时静止以动作迫使 60 尺内一个可见的大型或更小体型生物进行体质豁免，失败则被力场禁锢、速度降为 0 并陷入失能，直到你下回合结束或它受到任何伤害（次数等于智力调整值，长休恢复）；10 级奥法暂滞在消耗 4 环或更低法术位施法时把该法术封存进一颗 AC 为 15、1 点生命值且免疫毒素与心灵伤害的灰色小珠 1 小时，持珠者可用动作释放其中的法术，该法术使用你的法术攻击加值与豁免 DC（每次短休或长休一次）；14 级收束未来以反应跳过掷骰，直接指定结果为使该检定刚好成功的最低骰值或比它低 1 点的骰值，代价是获得一级只能靠长休消除的力竭。',
  'subclass-2014-wizard-graviturgy': 'Graviturgy Magic · EGtW · 理解并掌控将物质聚合或分离的力量，扭曲与操纵重力以增益自己、伤害敌人。2 级调节密度以动作把你 30 尺内一个可见的大型或更小体型物件或生物的重量减半或翻倍至多 1 分钟（如同专注，专注终止时提前结束）：重量减半者移动速度 +10 尺、跳跃距离变为两倍，但力量检定与力量豁免具有劣势；重量翻倍者移动速度减 10 尺，但力量检定与力量豁免具有优势（10 级起可作用于巨型或更小的目标）；6 级重力井在你将法术施展到生物身上时，只要目标自愿被移动、法术中的某次攻击命中它或它对抗该法术的豁免失败，你就能把它移动 5 尺至一处由你选择的未占据空间；10 级狂暴牵引可在 60 尺内可见生物（除你以外）的武器攻击命中时以反应追加 1d10 同类型伤害，或在 60 尺内生物承受坠落伤害时以反应使其增加 2d10（次数等于智力调整值，长休恢复）；14 级事件视界以动作散发 30 尺重力力场至多 1 分钟（如同专注），敌对生物在其中开始回合时须进行力量豁免，失败受 2d10 力场伤害且速度降为 0 直到其下回合开始，成功则伤害减半但每移动 1 尺需额外花费 2 尺移动力（长休一次，也可花 3 环或更高法术位再次使用）。',

  // ===== 吟游诗人学院 =====
  'subclass-2014-bard-lore': 'College of Lore · PHB · 以博学与机智拆解敌人的攻势。3 级附赠熟练获得任意三项技能熟练，语出惊人可用激励骰削减敌人的攻击、检定或伤害；6 级额外魔法奥秘从任意职业法术列表额外选取两个法术；14 级无双技艺可用激励骰强化自身的能力检定。',
  'subclass-2014-bard-valor': 'College of Valor · PHB · 以战歌鼓舞同伴并亲身上阵。3 级战斗激励让激励骰可用于武器伤害或提升 AC，并获中甲、盾牌与军用武器熟练；6 级额外攻击；14 级战斗魔法可在施展法术后以附赠动作发动一次武器攻击。',
  'subclass-2014-bard-glamour': 'College of Glamour · XGtE · 承袭妖精荒野的惑心魔法，把美好与恐怖织入歌舞。3 级惑心魔法始终准备魅惑类人与镜影术，施放惑控或幻术法术后可迫使 60 尺内一名生物感知豁免，失败则被魅惑或恐慌 1 分钟（每次长休一次，可消耗激励次数重置）；灵感织衣以附赠动作消耗激励骰，让至多等于魅力调整值名盟友获得双倍骰值的临时生命并立即移动；6 级威仪作锦始终准备命令术并可无需法术位施展，同时获得 1 分钟的超凡容貌；14 级不破威严让攻击你的敌人必须先行豁免。',
  'subclass-2014-bard-swords': 'College of Swords · XGtE · 刃锋以武器杂耍表演，同时是训练有素的战士。3 级附赠熟练获得中甲与弯刀熟练（并可用熟练的近战武器作为法器），战斗风格在决斗或双武器战斗中选择，剑舞可在攻击动作中以移动换取伤害或 AC 加成；6 级额外攻击；14 级剑舞大师使剑舞的移动换取效果进一步增强。',
  'subclass-2014-bard-whispers': 'College of Whispers · XGtE · 披着吟游诗人外衣收集秘密、制造恐惧。3 级心灵之刃在武器命中时消耗激励次数追加 2d6 心灵伤害（5 级 3d6、10 级 5d6、15 级 8d6），惊骇之语可在与类人生物交谈 1 分钟后迫使其感知豁免；6 级低语光环可窃取类人生物的外形；14 级阴暗学识可长期借用被窃取的外形。',
  'subclass-2014-bard-creation': 'College of Creation · TCoE · 引用创生圣言的造物之歌，让歌声具现为实体。3 级潜能微尘在给予诗人激励时附带一枚微尘，按激励骰的用途（属性检定／攻击检定／豁免检定）产生额外效果；6 级造物表演可以动作活化 30 尺内的物件或造出临时物品；14 级创造之赐在使用造物表演时可一次造出多件物品。',
  'subclass-2014-bard-eloquence': 'College of Eloquence · TCoE · 以无懈可击的逻辑与感染力说服听众。3 级巧舌如簧使魅力（游说）与魅力（欺瞒）检定掷出 9 或更低时视为 10，扰神之词以附赠动作消耗激励骰降低 60 尺内目标的下一次豁免；6 级不竭鼓舞让使用激励骰仍失败者可以保留该骰，统一言说使至多等于魅力调整值的生物听懂你的话语；14 级雄辩言辞使成功激励他人的效果向外扩散。',
  'subclass-2014-bard-spirits': 'College of Spirits · VRGtR · 以故事召引精魂，让传说化为力量。3 级呢喃指引额外习得戏法神导术（施法距离 60 尺，不占已知戏法），精魂法器允许用蜡烛、水晶球、头骨、通灵板或塔罗牌作为法器，彼岸故事以附赠动作消耗激励次数掷精魂故事表并保存故事；6 级精魂法器让通过法器施展的伤害或治疗法术获得一枚 d6 加值；14 级神秘连结使精魂故事更可控。',

  // ===== 德鲁伊结社（D1 第二批）=====
  'subclass-2014-druid-land': 'Circle of the Land · PHB · 守护自然的知识与仪式，与特定地形建立神秘链接。2 级附赠戏法额外学会一个德鲁伊戏法，自然恢复可在短休后回复环阶总和不超过德鲁伊等级一半（向下取整）的法术位（不含 6 环及以上，每次长休一次）；3／5／7／9 级按极地、海岸、荒漠、森林、草原、山地、沼泽或幽暗地域之一获得始终准备的结社法术；6 级大地行者穿越非魔法困难地形与植物不消耗额外移动力，对抗植物造成的移动限制时豁免具有优势；10 级自然之护免疫元素生物与妖精造成的魅惑与恐慌，并免疫中毒与疾病；14 级自然庇护所让野兽与植物类生物须先通过对抗你法术豁免 DC 的感知豁免才能攻击你。',
  'subclass-2014-druid-moon': 'Circle of the Moon · PHB · 凶猛的荒野卫士，以野兽形态亲临前线。2 级战斗荒野变形允许用附赠动作变形，并在变形期间以附赠动作消耗法术位恢复每环阶 1d8 生命值，结社形态把变身野兽的挑战等级上限提到 1；6 级结社形态把上限提高到德鲁伊等级除以 3（向下取整），原初打击让野兽形态的攻击视为魔法攻击；10 级元素荒野变形可消耗两次变形次数变成气、土、火或水元素；14 级千面相可随意施展变身术。',
  'subclass-2014-druid-dreams': 'Circle of Dreams · XGtE · 与妖精荒野的善良妖精结盟，以治愈和庇护守护同伴。2 级夏之王庭的芬馥提供等于德鲁伊等级枚 d6 的妖精能量池，可用附赠动作消耗至多一半枚数的骰子治疗 120 尺内的可见生物，并让它获得每枚骰子 1 点的临时生命值；6 级月光阴影的炉心在休息时造出半径 30 尺的隐形球体，让其中的隐匿与察觉检定 +5 并遮蔽明火的光亮；10 级隐匿通途可以附赠动作传送 60 尺，或以动作把自愿生物传送到 30 尺内，次数等于感知调整值（至少 1 次）；14 级梦境行者可在短休时无需法术位施展托梦术、探知术或传送法阵。',
  'subclass-2014-druid-shepherd': 'Circle of the Shepherd · XGtE · 沟通自然精魂，护卫并强化召唤出的野兽与妖精。2 级林地之语习得木族语并能与野兽交流，精魂图腾以附赠动作在 60 尺内召出半径 30 尺、持续 1 分钟的光环（熊精魂给出 5＋德鲁伊等级 点临时生命值并强化力量检定与豁免／鹰精魂以反应令攻击具有优势并强化察觉／独角兽精魂在你用法术位治疗时让光环内生物恢复等于德鲁伊等级的生命值），每次短休或长休后可再次使用；6 级全能牧者让召唤出的野兽与妖精每颗生命骰多 2 点生命值，天生武器视为魔法；10 级精魂守卫让光环内的召唤物每回合结束恢复一半德鲁伊等级的生命值；14 级忠诚牧畜在生命值归零或失能时免费获得 9 环动物咒唤术，召出四只挑战等级至多 2 的野兽，每次长休一次。',
  'subclass-2014-druid-spores': 'Circle of Spores · TCoE · 与真菌共生，看护腐朽与新生之间的循环。2 级结社法术让颤栗之触与后续法术始终准备，孢子环绕可用反应迫使 10 尺内生物进行体质豁免，失败受 1d4 暗蚀伤害（6 级 1d6、10 级 1d8、14 级 1d10），一体共生消耗一次荒野变形次数换取 4 倍德鲁伊等级的临时生命值、额外的伤害骰与近战命中追加 1d6 暗蚀伤害；6 级真菌感染可用反应把 10 尺内死亡的小型或中型野兽或类人生物化为丧尸（次数等于感知调整值，长休恢复）；10 级扩散孢子以附赠动作把孢子抛到 30 尺内，形成持续 1 分钟的 10 尺立方区域；14 级真菌之躯免疫目盲、耳聋、恐慌与中毒，且受到的暴击视为普通命中。',
  'subclass-2014-druid-stars': 'Circle of Stars · TCoE · 借星图与星座之力观测并扭转命运。2 级星图作为法器并提供戏法神导术与可免费施展的光导箭（次数等于熟练加值），星耀形态消耗一次荒野变形次数，在射手座（60 尺光箭造成 1d8＋感知调整值 光耀伤害）、圣杯座（消耗法术位施法后治疗 1d8＋感知调整值）与巨龙座（智力或感知检定、维持专注的体质豁免可把 d20 的 9 或更低视为 10）中三选一；6 级宇宙预兆按长休后掷骰的奇偶获得吉兆（反应加 1d6）或凶兆（反应减 1d6），次数等于熟练加值；10 级闪耀星座把射手座与圣杯座提升为 2d8，巨龙座额外提供 20 尺飞行与悬浮，并可在每回合开始时更换星座；14 级灿若繁星在星耀形态下获得钝击、穿刺与挥砍伤害抗性。',
  'subclass-2014-druid-wildfire': 'Circle of Wildfire · TCoE · 与兼具创生与毁灭的原初火之精魂相连。2 级结社法术让燃烧之手、疗伤术等始终准备，召唤野火灵魄消耗一次荒野变形次数召出小型元素（HP 为 5＋五倍德鲁伊等级，免疫火焰，火种造成 1d6＋熟练加值 火焰伤害，烈焰传送可带走 5 尺内的自愿生物），出现时 10 尺内的其他生物需通过敏捷豁免否则受 2d6 火焰伤害；6 级强化链接让造成火焰伤害或恢复生命的法术获得一枚 d8 加值，并可把非自身射程的法术改从灵魄发出；10 级灼烧烈焰在生物死亡处留下幽火，可用反应造成或治疗 2d10＋感知调整值，次数等于熟练加值；14 级炽烈回生可在昏迷时牺牲 120 尺内的灵魄，让自己恢复一半生命值。',

  // ===== 战士武术范型（D1 第二批）=====
  'subclass-2014-fighter-champion': 'Champion · PHB · 只凭肉体与意志的纯粹武者，靠更广的重击范围与稳定体能取胜。3 级精通重击让武器攻击掷出 19 或 20 即可重击；7 级运动健将把一半熟练加值（向上取整）加到尚未包含熟练的力量、敏捷、体质检定上，助跑跳远的距离增加等于力量调整值的尺数；10 级额外战斗风格再选一个战斗风格；15 级高效重击把重击范围扩大到 18—20；18 级生还者在每回合开始时若生命值不到上限的一半，就恢复 5＋体质调整值 点生命值。',
  'subclass-2014-fighter-battle-master': 'Battle Master · PHB · 以卓越骰驱动战技的战术型武者，靠自选战技完成控制、增益与机动。3 级卓越战技习得 3 种战技（7、10、15 级各再学 2 种并可替换一个已知战技），拥有 4 枚 d8 卓越骰（7 级 5 枚、15 级 6 枚，短休或长休恢复），战技豁免 DC 为 8＋熟练加值＋力量或敏捷调整值；3 级战争学徒获得一项工匠工具熟练；7 级知己知彼在观察或交互至少 1 分钟后由地下城主告知目标的两项强弱对比；10 级精通卓越战技把卓越骰提升为 d10（18 级 d12）；15 级坚韧在骰先攻且无卓越骰可用时获得 1 枚。可选战技含精准攻击、摔绊攻击、推撞攻击、缴械攻击、挑衅攻击、恐吓攻击、横扫攻击、反击、格挡等，TCoE 另有伏击、换位诈术、快手投掷等扩充选项。',
  'subclass-2014-fighter-eldritch-knight': 'Eldritch Knight · PHB · 把法师的防护与塑能法术织入剑术的混合战斗者，以智力施法。3 级施法学会 2 个法师戏法与 3 个法师法术（其中两个须来自防护系与塑能系），10 级再添一个戏法，8／14／20 级可学习任意学派的法术；3 级武器联结用 1 小时仪式联结武器（至多 2 把），不处于失能时不会被缴械，并可用附赠动作把同一位面的联结武器召回手中；7 级战争魔法允许以动作施展戏法后用附赠动作发动一次武器攻击；10 级秘法打击让被武器命中的生物对抗你下一个法术的豁免具有劣势；15 级秘法冲锋可在动作如潮时传送至多 30 尺；18 级精通战争魔法允许施法后以附赠动作发动一次武器攻击。',
  'subclass-2014-fighter-purple-dragon-knight': 'Purple Dragon Knight · SCAG · 科米尔的骑士领袖（别名旗将 Banneret），用自身的回复能力带动全队。3 级重整姿态在使用回气时可让 60 尺内至多 3 个能看见或听见你的友好生物各恢复等于你战士等级的生命值；7 级皇家特使获得游说熟练（已熟练则改选驯兽、洞悉、威吓或表演之一），进行魅力（游说）检定时加入双倍熟练加值；10 级振奋之潮在使用动作如潮时让 60 尺内一个友好生物以反应发动一次武器攻击（18 级起改为两个）；15 级意志壁垒在使用不屈重骰智力、感知或魅力豁免时，可让 60 尺内一名因同一效应豁免失败的盟友重骰该豁免。',
  'subclass-2014-fighter-arcane-archer': 'Arcane Archer · XGtE · 精灵箭术传统，把魔法注入弓矢制造超自然箭效。3 级魔箭学识获得奥秘或自然之一的熟练并习得魔法伎俩或德鲁伊伎俩，奥术射击学会 2 种射击选项（7、10、15、18 级各再加 1 种），每回合一次可在用短弓或长弓射出箭矢时附加一个选项，使用次数 2 次（短休或长休恢复），豁免 DC 为 8＋熟练加值＋智力调整值；可选射击包括放逐矢、欺诈矢、爆裂矢、虚弱矢、缠绕矢、穿梭矢、追踪矢与遮影矢；7 级注魔箭矢让射出的非魔法箭矢视为魔法，曲线射击可在未命中时以附赠动作对 60 尺内的另一目标重掷该次攻击；15 级有箭无患在骰先攻且次数耗尽时重获一次；18 级时全部射击选项强化。',
  'subclass-2014-fighter-cavalier': 'Cavalier · XGtE · 乘骑与护卫专精的贵族武士，以印记迫使敌人回头攻击自己。3 级附赠熟练获得驯兽、历史、洞悉、表演或游说之一的熟练（或一门语言），生而为骑在避免坠马的豁免上具有优势、从不超过 10 尺的高度落地可双脚着地、上下坐骑只花 5 尺移动力，坚定之印让被近战命中的敌人在你 5 尺内攻击他人时具有劣势，若它伤害了他人，你可在下回合以附赠动作发动具有优势的特殊攻击并追加一半战士等级的伤害（次数等于力量调整值，长休恢复）；7 级守护战技以反应为自己或 5 尺内可见生物加上 1d8 AC，若仍被命中则该次伤害具有抗性（次数等于体质调整值，长休恢复）；10 级坚守战线让触及范围内的移动引发借机攻击，命中后目标速度降为 0；15 级冲锋陷阵在直线移动 10 尺并命中时迫使目标力量豁免（DC 为 8＋熟练加值＋力量调整值），失败则倒地；18 级警戒守卫在每个其他生物的回合都能额外使用一次只能用于借机攻击的反应。',
  'subclass-2014-fighter-samurai': 'Samurai · XGtE · 以坚决意志自我强化的单挑型战士，用战意换取优势与韧性。3 级附赠熟练获得历史、洞悉、表演或游说之一的熟练（或一门语言），战意可以附赠动作为本回合的武器攻击提供优势并获得 5 点临时生命值（10 级 10 点、15 级 15 点），可用 3 次并在长休后恢复；7 级雅臣在进行魅力（游说）检定时加入感知调整值，并获得感知豁免熟练（已有则改选智力或魅力豁免）；10 级不懈在骰先攻且战意耗尽时重获一次；15 级燕返可放弃一次具有优势的攻击检定，对同一目标追加一次攻击；18 级生死流转在受到致命伤害时以反应延缓昏迷并获得一个额外回合，每次长休一次。',
  'subclass-2014-fighter-echo-knight': 'Echo Knight · EGTW · 克灵王朝的前线斗士，召出未实现时间线中的回音作为第二个攻击与移动原点。3 级回音显现以附赠动作在 15 尺内显现回音（AC 为 14＋熟练加值、1 点生命值、免疫所有状态、与你同体型，回合结束时若距你超过 30 尺即消散），可用思想让它移动至多 30 尺、以附赠动作消耗 15 尺移动力与之换位、从它的位置发出攻击，并在它 5 尺内的生物远离时借机攻击；3 级释放化身在每次执行攻击动作时于回音位置追加一次近战攻击（次数等于体质调整值，长休恢复）；7 级回音现身可用回音的感官观察与聆听至多 10 分钟，此时它可离你至多 1000 尺；10 级影之殉难以反应让回音代受一次攻击（短休或长休一次）；15 级回收潜能可在回音被摧毁时获得 2d6＋体质调整值 点临时生命值；18 级一人成军可一次召出两个回音，并在骰先攻时补回释放化身的次数。',
  'subclass-2014-fighter-psi-warrior': 'Psi Warrior · TCoE · 觉醒内在心灵力量的战士，以灵能骰驱动念力。3 级灵能力量提供等于两倍熟练加值的 d6 灵能骰（5 级 d8、11 级 d10、17 级 d12，长休全恢复，并可用附赠动作回复一枚但每次休息限一次），庇护力场以反应为 30 尺内的自己或他人减少灵能骰＋智力调整值 点伤害，灵能打击每回合一次在武器命中时追加灵能骰＋智力调整值 的力场伤害，念力控物以动作把 30 尺内至多大型的物体或一名自愿生物移动至多 30 尺；7 级念力擅长让灵力跃动以附赠动作获得两倍步行速度的飞行速度，念力突刺在灵能打击造成伤害后迫使目标力量豁免（DC 为 8＋熟练加值＋智力调整值），失败则倒地或被水平推开至多 10 尺；10 级意念守护获得心灵伤害抗性，并可用灵能骰结束自身的魅惑与恐慌；15 级壁垒之力以附赠动作给等于智力调整值数量的 30 尺内生物 1 分钟半身掩护；18 级念力宗师可无需成分施展心灵遥控并以附赠动作追加武器攻击。',
  'subclass-2014-fighter-rune-knight': 'Rune Knight · TCoE · 沿袭巨人传统的符文刻录者，把符文铭刻在装备上取得被动增益与主动威能。3 级额外熟练项获得铁匠工具熟练与巨人语，符文雕刻者学会 2 个符文（7 级 3 个、10 级 4 个、15 级 5 个），每次长休可把符文铭刻到等于已知符文数的武器、护甲、盾牌或首饰上，符文豁免 DC 为 8＋熟练加值＋体质调整值，云雾符文可转移一次命中的攻击，火焰符文追加 2d6 火焰伤害并束缚目标 1 分钟，寒霜符文提供 10 分钟内力量与体质检定及豁免 +2，岩石符文以反应魅惑并令目标失能，山丘符文与风暴符文需 7 级（分别提供钝击、挥砍、穿刺抗性，或 1 分钟的先知形态）；3 级巨人之力以附赠动作变大至大型、力量检定与豁免具有优势、每回合一次追加 1d6 伤害（次数等于熟练加值，长休恢复）；7 级符文之盾以反应迫使攻击者重掷 d20；10 级奇伟身躯让身高增加 3d4 英寸并把巨人之力的伤害提升为 1d8；15 级符文大师让每个符文可激活两次并在短休或长休后恢复；18 级符文主宰把伤害提升为 1d10，并可变为巨型、触及 +5 尺。',

  // ===== 牧师神圣领域（D1 第二批）=====
  'subclass-2014-cleric-life': 'Life Domain · PHB · 掌握维系众生的正能量，是最纯粹的治愈路线。1 级生命门徒让消耗法术位恢复生命的法术额外恢复 2＋法术环阶 点生命值，并获得重甲熟练与始终准备的领域法术（祝福术、疗伤术、次等复原术、灵体武器、希望信标、回生术、防死结界、信仰守卫、群体疗伤术、死者复活）；2 级引导神力维持生命以一个动作把等于牧师等级 5 倍的治疗量分配给 30 尺内的任意生物，至多把目标补到生命值上限的一半，且不能作用于亡灵与构装生物；6 级神佑医者在对他人施放治疗法术时也为自己恢复 2＋法术环阶 点生命值；8 级神圣打击每回合一次在武器命中时追加 1d8 光耀伤害（14 级 2d8）；17 级极效治疗让所有治疗骰直接取最大值。',
  'subclass-2014-cleric-light': 'Light Domain · PHB · 光明与火焰的爆发型施法牧师，用光耀与火焰烧尽晦暗、破除幻象。1 级附赠戏法获得光亮术，守御闪光可用反应让 30 尺内攻击你的生物具有劣势（次数等于感知调整值，长休恢复）；2 级引导神力黎明曙光以一个动作驱散 30 尺内的魔法黑暗，并迫使 30 尺内每个敌对生物进行体质豁免，失败受 2d10＋牧师等级 光耀伤害、成功减半（相对你处于全身掩护者不受影响）；6 级精通闪光让守御闪光也能用于 30 尺内攻击他人的生物；8 级强力施法为牧师戏法的伤害加上感知调整值；17 级光冕以动作放出半径 60 尺明亮光照与其外 30 尺微光光照并持续 1 分钟，其中的敌人为抵抗火焰或光耀伤害法术而进行的豁免具有劣势。',
  'subclass-2014-cleric-knowledge': 'Knowledge Domain · PHB · 以技能与情报取胜的牧师，靠双倍熟练、临时技能与读心掌控局面。1 级知识祝福学会两门语言，并从奥秘、历史、自然、宗教中选两项获得熟练，对这两项进行的属性检定加入双倍熟练加值；2 级引导神力岁月知识以动作指定一个技能或工具，在随后 10 分钟内视为拥有其熟练项；6 级引导神力读心以动作迫使 60 尺内一个可见生物进行感知豁免，失败则你可读取其表层思想 1 分钟，并可用动作无需法术位施展暗示术而目标豁免直接判为失败（豁免成功者直到你完成长休前不能再次被该特性指定）；8 级强力施法为牧师戏法的伤害加上感知调整值；17 级透视过去通过至少 1 分钟冥想解读物件的旧主或 50 尺立方区域的往事，可回溯的日数等于感知值，用后须短休或长休。',
  'subclass-2014-cleric-nature': 'Nature Domain · PHB · 披重甲、通元素的自然牧师，以魅惑动植物与元素抗性支援全队。1 级自然侍僧习得一个不计入已知戏法的德鲁伊戏法，并获得驯兽、自然、生存之一的熟练，附赠熟练项提供重甲熟练；2 级引导神力魅惑动植物以动作迫使 30 尺内可见的野兽与植物生物进行感知豁免，失败者被魅惑 1 分钟或直到受伤，期间对你与你指定的生物友善；6 级抑制元素以反应让 30 尺内的自己或他人获得对那次强酸、寒冷、火焰、闪电或雷鸣伤害的抗性；8 级神圣打击每回合一次在武器命中时追加 1d8 寒冷、火焰或闪电伤害（14 级 2d8）；17 级自然之主以附赠动作下达口头指令，让所有被你魅惑的生物在其下一回合执行。',
  'subclass-2014-cleric-tempest': 'Tempest Domain · PHB · 披重甲、持军用武器的雷鸣闪电牧师，靠最大化伤害骰与击退压制战场。1 级附赠熟练项获得军用武器与重甲熟练，风暴狂怒在 5 尺内生物命中你时以反应迫使它进行敏捷豁免，失败受 2d8 闪电或雷鸣伤害、成功减半（次数等于感知调整值，长休恢复）；2 级引导神力毁灭狂怒让一次闪电或雷鸣伤害的伤害掷骰直接取最高值；6 级雷霆打击在造成闪电伤害时把大型或更小的目标向远离你的方向推开至多 10 尺；8 级神圣打击每回合一次追加 1d8 雷鸣伤害（14 级 2d8）；17 级风暴降生在不处于地底或室内时获得等于步行速度的飞行速度。',
  'subclass-2014-cleric-trickery': 'Trickery Domain · PHB · 用幻象与潜行欺骗敌人的牧师，靠分身复制施法位置并制造优势。1 级诡术祝福以动作触碰一名除你以外的自愿生物，让它在敏捷（隐匿）检定上具有优势，持续 1 小时或直到你再次使用；2 级引导神力召唤分身以动作在 30 尺内造出一个持续 1 分钟的自身幻象（需如法术般专注），可用附赠动作让它移动至多 30 尺且始终保持在你 120 尺内，你能从它的位置施展法术，当你与它都在目标 5 尺内且目标能看见它时，你对该目标的攻击检定具有优势；6 级引导神力幽影斗篷以动作隐形直到你的下一回合结束，攻击或施法后随即显形；8 级神圣打击每回合一次追加 1d8 毒素伤害（14 级 2d8）；17 级精通分身让召唤分身一次造出至多 4 个幻象，并可用附赠动作移动其中任意数量。',
  'subclass-2014-cleric-war': 'War Domain · PHB · 前线增益型战斗牧师，用附赠动作的额外攻击与 +10 命中把武器伤害压满。1 级额外熟练项获得军用武器与重甲熟练，战争祭司在执行攻击动作时可用附赠动作发动一次武器攻击（次数等于感知调整值，长休恢复）；2 级引导神力导引打击让一次攻击检定获得 +10 加值，可在看到掷骰结果后、得知是否命中前决定是否使用；6 级引导神力战神祝福以反应让 30 尺内一个生物的攻击检定获得 +10 加值，判定时机同上；8 级神圣打击每回合一次追加 1d8 与武器同类型的伤害（14 级 2d8）；17 级战斗化身获得对非魔法攻击的钝击、穿刺与挥砍伤害抗性。',
  'subclass-2014-cleric-death': 'Death Domain · DMG · 掌控死亡原力与负能量的领域，多为反派或 NPC 牧师，玩家选用须经地下城主同意。1 级附赠熟练获得军用武器熟练，收割者从任意法术列表学会一个死灵系戏法，并让原本只指定一个生物的死灵系戏法可以改为指定施法距离内相互距离不超过 5 尺的两个生物；2 级引导神力死亡之触在近战命中时追加 5＋两倍牧师等级 的暗蚀伤害；6 级命定毁伤让牧师法术与引导神力造成的暗蚀伤害无视暗蚀伤害抗性；8 级神圣打击每回合一次追加 1d8 暗蚀伤害（14 级 2d8）；17 级精通收割者把只指定单个生物的 1—5 环死灵法术改为指定相互距离不超过 5 尺的两个生物，若法术消耗材料成分则须为每个目标各提供一份。',
  'subclass-2014-cleric-arcana': 'Arcana Domain · SCAG · 窃取法师秘法的牧师，把 6—9 环法师法术纳入领域法术并善于放逐异界生物。1 级奥术传承获得奥秘技能熟练，并从法师法术列表习得两个视为牧师戏法的戏法；2 级引导神力奥秘阻绝以动作迫使 30 尺内一个天族、元素、妖精或邪魔进行感知豁免，失败则被驱散 1 分钟（它须尽力远离你、无法主动靠近你 30 尺内、不能用反应、只能疾走或挣脱），5 级起对挑战等级足够低且非本位面的生物改为放逐 1 分钟（5 级 CR 1/2、8 级 CR 1、11 级 CR 2、14 级 CR 3、17 级 CR 4）；6 级破法者在你用 1 环或更高环阶法术为盟友恢复生命时，可同时终止其身上一个环阶低于该法术位的法术；8 级强力施法为牧师戏法的伤害加上感知调整值；17 级奥术精通从法师法术列表为 6、7、8、9 环各选一个法术加入领域法术并始终准备。',
  'subclass-2014-cleric-forge': 'Forge Domain · XGtE · 披重甲的工匠型牧师，用造物仪式与装备附魔武装全队。1 级额外熟练项获得重甲与铁匠工具熟练，锻造祝福在长休结束时把一件非魔法护甲或武器变为魔法物品（护甲 AC +1，武器攻击与伤害 +1）直到下次长休，每次长休只能使用一次；2 级引导神力铁匠祝福用 1 小时仪式造出价值低于 100 gp 的含金属非魔法物品或它的复制品，需提供等值金属作为材料；6 级锻造之魂获得火焰伤害抗性，穿重甲时 AC +1；8 级神圣打击每回合一次追加 1d8 火焰伤害（14 级 2d8）；17 级锻炉与烈焰的圣徒获得火焰伤害免疫，穿重甲时对非魔法攻击的钝击、穿刺与挥砍伤害具有抗性。',
  'subclass-2014-cleric-grave': 'Grave Domain · XGtE · 站在生死边界的守门人，擅长把同伴从死亡线上拉回并封锁敌人的重击。1 级生死轮回让为生命值为 0 的生物恢复生命的治疗骰全部取满值，并习得戏法维生术（不占已知戏法，对你而言射程 30 尺且可用附赠动作施展），坟墓之眼以动作感知 60 尺内未被全身掩护或预言魔法遮蔽的亡灵（次数等于感知调整值，长休恢复）；2 级引导神力往墓之途以动作诅咒 30 尺内一个可见生物，直到你下回合结束前它被下一次攻击命中时对那次攻击的全部伤害具有易伤；6 级死之门的哨卫以反应把 30 尺内自己或盟友受到的一次重击变为普通命中并取消其附加效应（次数等于感知调整值，长休恢复）；8 级强力施法为牧师戏法的伤害加上感知调整值；17 级引魂明灯在 60 尺内可见敌人死亡时，让你或 60 尺内由你选择的一个生物恢复等于该敌人生命骰数量的生命值。',
  'subclass-2014-cleric-order': 'Order Domain · TCoE · 以律法与指挥支援盟友的牧师，让队友借你的法术白赚一次攻击。1 级附赠熟练项获得重甲熟练以及威吓或游说之一的熟练，权威之音让你消耗法术位施展法术并以盟友为目标时，该盟友可立即以反应对你指定且它能看见的目标发动一次武器攻击（目标多于一个时由你选择）；2 级引导神力秩序之令以动作展示圣徽，30 尺内你指定的能看到或听到你的生物须通过感知豁免，失败则被你魅惑直到你下回合结束或受伤，且你可让被魅惑者扔掉手持物；6 级律法化身在以 1 环或更高环阶法术位施展施法时间为 1 动作的惑控法术时，把施法时间改为 1 附赠动作（次数等于感知调整值，长休恢复）；8 级神圣打击每回合一次追加 1d8 心灵伤害（14 级 2d8）；17 级秩序之怒在造成神圣打击后诅咒该生物，你的盟友下一次命中它时它额外受 2d8 心灵伤害。',
  'subclass-2014-cleric-peace': 'Peace Domain · TCoE · 以联结之力支援团队的牧师，让全队的攻击、检定与豁免都更稳。1 级和平执行获得洞悉、表演或游说之一的熟练，勇气联结以动作让 30 尺内等于熟练加值数量的自愿生物彼此联结 10 分钟：任一联结生物 30 尺内有其他联结生物时，它的攻击检定、属性检定或豁免检定可额外加一枚 d4（每回合一次），次数等于熟练加值并在长休后恢复；2 级引导神力和平抚慰以动作移动等于速度的距离且不引发借机攻击，途中移动到任何生物 5 尺内都可为其恢复 2d6＋感知调整值 点生命值（每个生物每次只得一次）；6 级保护联结让 30 尺内另一联结生物以反应传送到受伤者 5 尺内并代替其承受全部伤害；8 级强力施法为牧师戏法的伤害加上感知调整值；17 级增强联结把联结距离放宽到 60 尺，且代替他人承受伤害者被视为具有该伤害的抗性。',
  'subclass-2014-cleric-twilight': 'Twilight Domain · TCoE · 守护黑夜与幽域的牧师，为队伍提供超远黑暗视觉、团队圣域与飞行。1 级附赠熟练项获得军用武器与重甲熟练，黑夜明目提供 300 尺黑暗视觉（黑暗中视为微光、微光中视为明亮）并可以动作分享给 10 尺内等于感知调整值数量的自愿生物 1 小时（每次长休一次，也可消耗任意环阶法术位再次分享），警觉赐福以动作让一个生物的下一次先攻检定具有优势；2 级引导神力暮光圣域以动作散发跟随自己、半径 30 尺、持续 1 分钟的微光球体，每个在球体中结束回合的生物可选择获得 1d6＋牧师等级 点临时生命值，或结束一项正使它魅惑或恐慌的效应；6 级午夜飞步在微光或黑暗中以附赠动作获得等于步行速度的飞行速度 1 分钟（次数等于熟练加值，长休恢复）；8 级神圣打击每回合一次追加 1d8 光耀伤害（14 级 2d8）；17 级暮光守护让球体内的你与盟友获得半身掩护。',
}

